-- ============================================================================
-- Display names: every record and table shows "Surname, Firstname M.".
--
-- The name-building concatenations in these response functions are replaced
-- with lirc_private.person_name (the same formatter the station and the desk
-- scanner already use). Search predicates keep matching the space-separated
-- form, so typing "Sam Villanueva" still finds the record.
--
-- Generated by scripts/build-name-format-migration.mjs from the current
-- definitions; only the name expressions change.
-- ============================================================================
begin;

-- Text flavour of the formatter for subquery rows (which are not usersData
-- composites), e.g. the statistics top-borrower lists.
create or replace function lirc_private.person_name(
  p_first text,
  p_middle text,
  p_surname text,
  p_suffix text default null)
returns text
language plpgsql
immutable
security definer
set search_path = ''
as $$
declare
  mi text;
  given text;
  base text;
begin
  mi := nullif(btrim(coalesce(p_middle, '')), '');
  if mi is not null and right(mi, 1) <> '.' then
    mi := mi || '.';
  end if;
  given := nullif(concat_ws(' ', nullif(btrim(coalesce(p_first, '')), ''), mi), '');
  base := concat_ws(', ', nullif(btrim(coalesce(p_surname, '')), ''), given);
  return nullif(concat_ws(' ', base, nullif(btrim(coalesce(p_suffix, '')), '')), '');
end $$;
revoke all on function lirc_private.person_name(text, text, text, text)
  from public, anon, authenticated;

-- lirc_private.filtered_attendance
create or replace function lirc_private.filtered_attendance(period_id bigint,f jsonb,across_periods boolean)
returns setof jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('id',a.id,'user_profile_id',a.user_profile_id,'semester_id',a.semester_id,
  'full_name',lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),'library_id',u.library_id,
  'role',a.role_at_visit,'year_level',a.year_level,'year_level_note',a.year_level_note,'purpose',a.purpose_of_visit,
  'time_in',a.time_in,'time_out',a.time_out,'created_at',a.created_at,
  'duration',case when a.time_out is null then null else extract(epoch from a.time_out-a.time_in)/60 end,
  'department',u.department_label,'program',u.program_label,'position',u.position_label,
  'recorded_by',lirc_private.person_name(rec.first_name, rec.middle_initial, rec.surname, rec.suffix),'checked_out_by',lirc_private.person_name(out_staff.first_name, out_staff.middle_initial, out_staff.surname, out_staff.suffix),
  'semester',ay.name||' · '||s.name,'current_enrollment_status',case when a.role_at_visit='student' then coalesce(e.status,'unverified') else 'Not applicable' end)
 from public.attendance a join lirc_private.profile_dimensions u on u.id=a.user_profile_id
 join public.semesters s on s.id=a.semester_id join public.academic_years ay on ay.id=s.academic_year_id
 left join public.student_enrollments e on e.id=a.student_enrollment_id and e.academic_year_id=s.academic_year_id
 left join public."usersData" rec on rec.id=a.recorded_by left join public."usersData" out_staff on out_staff.id=a.checked_out_by
 where (case when across_periods then a.time_out is null else a.semester_id=period_id end)
 and lirc_private.report_search(to_jsonb(u),f)
 and (coalesce(f->>'role','')='' or a.role_at_visit=f->>'role')
 and (coalesce(f->>'status','')='' or (f->>'status'='open' and a.time_out is null) or (f->>'status'='completed' and a.time_out is not null))
 and (coalesce(f->>'year_level','')='' or (f->>'year_level'='na' and a.year_level is null) or a.year_level::text=f->>'year_level')
 and lirc_private.report_classification(u.classification_department,f->>'department')
 and lirc_private.report_classification(u.classification_program,f->>'program')
 and lirc_private.report_classification(u.classification_position,f->>'position')
 and (coalesce(f->>'purpose','')='' or a.purpose_of_visit=f->>'purpose' or (f->>'purpose'='Other' and a.purpose_of_visit not in ('Reading','Studying','Research','Borrowing/Returning','Computer Use')))
 and (coalesce(f->>'purpose_text','')='' or strpos(lower(a.purpose_of_visit),lower(f->>'purpose_text'))>0)
 and (nullif(f->>'arrival_from','') is null or a.time_in >= (f->>'arrival_from')::timestamptz) and (nullif(f->>'arrival_to','') is null or a.time_in < (f->>'arrival_to')::timestamptz)
 and (nullif(f->>'departure_from','') is null or a.time_out >= (f->>'departure_from')::timestamptz) and (nullif(f->>'departure_to','') is null or a.time_out < (f->>'departure_to')::timestamptz)
 and (nullif(f->>'time_start','') is null or (a.time_in at time zone 'Asia/Manila')::time >= (f->>'time_start')::time)
 and (nullif(f->>'time_end','') is null or (a.time_in at time zone 'Asia/Manila')::time <= (f->>'time_end')::time)
 and (nullif(f->>'duration_min','') is null or (a.time_out is not null and extract(epoch from a.time_out-a.time_in)/60 >= (f->>'duration_min')::numeric))
 and (nullif(f->>'duration_max','') is null or (a.time_out is not null and extract(epoch from a.time_out-a.time_in)/60 <= (f->>'duration_max')::numeric))
 and (nullif(f->>'elapsed_min','') is null or (a.time_out is null and extract(epoch from now()-a.time_in)/60 >= (f->>'elapsed_min')::numeric))
 and (nullif(f->>'elapsed_max','') is null or (a.time_out is null and extract(epoch from now()-a.time_in)/60 <= (f->>'elapsed_max')::numeric))
 and (coalesce(f->>'recorded_by','')='' or a.recorded_by::text=f->>'recorded_by')
 and (coalesce(f->>'checked_out_by','')='' or (f->>'checked_out_by'='none' and a.checked_out_by is null) or a.checked_out_by::text=f->>'checked_out_by')
 and (coalesce(f->>'enrollment_status','')='' or (f->>'enrollment_status'='na' and a.role_at_visit<>'student') or (a.role_at_visit='student' and coalesce(e.status,'unverified')=f->>'enrollment_status'))
 and (coalesce(f->>'note','')='' or (f->>'note'='yes' and nullif(a.year_level_note,'') is not null) or (f->>'note'='no' and nullif(a.year_level_note,'') is null));
$$;

-- lirc_private.filtered_annual_enrollment
create or replace function lirc_private.filtered_annual_enrollment(year_id bigint,f jsonb)
returns setof jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('id',u.id,'profile',jsonb_build_object('id',u.id,'library_id',u.library_id,'first_name',u.first_name,'surname',u.surname,'middle_initial',u.middle_initial,'suffix',u.suffix,'role',u.role),
  'full_name',lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),'library_id',u.library_id,
  'enrollment',case when e.id is null then null else to_jsonb(e) end,'status',coalesce(e.status,'unverified'),'year_level',e.year_level,
  'estimated_level',estimate.level,'validated_at',e.validated_at,'created_at',e.created_at,'updated_at',e.updated_at,
  'validator',lirc_private.person_name(validator.first_name, validator.middle_initial, validator.surname, validator.suffix),'department',u.department_label,'program',u.program_label,
  'auth_linked',u.user_id is not null)
 from lirc_private.profile_dimensions u cross join public.academic_years ay
 left join public.student_enrollments e on e.user_profile_id=u.id and e.academic_year_id=ay.id
 left join public."usersData" validator on validator.id=e.validated_by
 cross join lateral (select case when u.library_id ~ '^[0-9]{2}-' then ay.start_year-(2000+substring(u.library_id from 1 for 2)::int)+1 else null end raw) admission
 cross join lateral (select case when admission.raw between 1 and 10 then admission.raw else null end level) estimate
 where ay.id=year_id and lower(btrim(u.role))='student'
 and lirc_private.report_search(to_jsonb(u),f)
 and lirc_private.report_classification(u.classification_department,f->>'department')
 and lirc_private.report_classification(u.classification_program,f->>'program')
 and (coalesce(f->>'cohort','')='' or (u.library_id ~ '^[0-9]{2}-' and substring(u.library_id from 1 for 2)=f->>'cohort'))
 and (coalesce(f->>'status','')='' or coalesce(e.status,'unverified')=f->>'status')
 and (coalesce(f->>'year_level','')='' or (f->>'year_level'='none' and e.year_level is null) or e.year_level::text=f->>'year_level')
 and (coalesce(f->>'estimated_level','')='' or (f->>'estimated_level'='none' and estimate.level is null) or estimate.level::text=f->>'estimated_level')
 and (coalesce(f->>'conflict','')='' or (f->>'conflict'='unsupported' and estimate.level is null) or (f->>'conflict'='unverified' and e.year_level is null) or (f->>'conflict'='matches' and e.year_level=estimate.level) or (f->>'conflict'='differs' and e.year_level<>estimate.level))
 and (coalesce(f->>'validation_state','')='' or (f->>'validation_state'='missing' and e.id is null) or (f->>'validation_state'='unverified' and e.id is not null and e.validated_at is null) or (f->>'validation_state'='validated' and e.validated_at is not null))
 and (coalesce(f->>'auth','')='' or (f->>'auth'='yes' and u.user_id is not null) or (f->>'auth'='no' and u.user_id is null))
 and (coalesce(f->>'validator','')='' or e.validated_by::text=f->>'validator')
 and (nullif(f->>'validated_from','') is null or e.validated_at >= (f->>'validated_from')::timestamptz)
 and (nullif(f->>'validated_to','') is null or e.validated_at < (f->>'validated_to')::timestamptz)
 and (coalesce(f->>'reference','')='' or strpos(lower(e.validation_reference),lower(f->>'reference'))>0)
 and (coalesce(f->>'notes','')='' or strpos(lower(e.year_level_note),lower(f->>'notes'))>0);
$$;

-- public.lirc_student_validation_history
create or replace function public.lirc_student_validation_history(p_profile_id bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  result jsonb;
begin
  if lirc_private.attendance_staff_id() is null then
    raise exception 'Staff access required.' using errcode = '42501';
  end if;
  if not exists (select 1 from public."usersData" where id = p_profile_id) then
    raise exception 'Library member not found.';
  end if;
  select jsonb_build_object('years', coalesce(jsonb_agg(jsonb_build_object(
      'academic_year_id', x.id,
      'name', x.name,
      'starts_on', x.starts_on,
      'ends_on', x.ends_on,
      'is_past', x.is_past,
      'before_admission', x.before_admission,
      'enrollment_id', x.enrollment_id,
      'status', x.status,
      'year_level', x.year_level,
      'year_level_source', x.year_level_source,
      'validated_at', x.validated_at,
      'validator', x.validator,
      'pending', x.pending
    ) order by x.start_year desc), '[]'::jsonb))
  into result
  from (
    select ay.id, ay.name, ay.start_year, ay.starts_on, ay.ends_on,
      ((now() at time zone 'Asia/Manila')::date > ay.ends_on) as is_past,
      case when u.library_id ~ '^[0-9]{2}-'
           then ay.start_year < 2000 + substring(u.library_id from 1 for 2)::integer
           else false end as before_admission,
      e.id as enrollment_id, e.status, e.year_level, e.year_level_source,
      e.validated_at,
      nullif(lirc_private.person_name(ve.first_name, ve.middle_initial, ve.surname, ve.suffix), '') as validator,
      case when r.id is null then null else jsonb_build_object(
        'id', r.id,
        'requested_status', r.requested_status,
        'previous_status', r.previous_status,
        'requested_by', nullif(lirc_private.person_name(rb.first_name, rb.middle_initial, rb.surname, rb.suffix), ''),
        'created_at', r.created_at) end as pending
    from public.academic_years ay
    cross join public."usersData" u
    left join public.student_enrollments e
      on e.user_profile_id = u.id and e.academic_year_id = ay.id
    left join public."usersData" ve on ve.id = e.validated_by
    left join public.enrollment_change_requests r
      on r.user_profile_id = u.id and r.academic_year_id = ay.id and r.status = 'pending'
    left join public."usersData" rb on rb.id = r.requested_by
    where u.id = p_profile_id
  ) x;
  return result;
end $$;

-- public.lirc_request_enrollment_change
create or replace function public.lirc_request_enrollment_change(
  p_profile_id bigint, p_academic_year_id bigint, p_status text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_staff bigint;
  v_is_past boolean;
  v_previous text;
  v_student text;
  v_year text;
begin
  v_staff := lirc_private.attendance_staff_id();
  if v_staff is null then
    raise exception 'Staff access required.' using errcode = '42501';
  end if;
  if p_status not in ('enrolled','unverified','leave_of_absence','withdrawn','graduated') then
    raise exception 'Invalid status.';
  end if;
  if not exists (select 1 from public."usersData" where id = p_profile_id) then
    raise exception 'Library member not found.';
  end if;
  select (now() at time zone 'Asia/Manila')::date > ay.ends_on, ay.name
    into v_is_past, v_year
    from public.academic_years ay
   where ay.id = p_academic_year_id;
  if v_year is null then raise exception 'Academic year not found.'; end if;
  if not v_is_past then
    raise exception 'This school year is current. Save it directly instead of requesting approval.';
  end if;

  -- Admins are the approvers: their past-year edits apply immediately.
  if lirc_private.is_admin() then
    perform lirc_private.apply_enrollment_change(p_profile_id, p_academic_year_id, p_status);
    return jsonb_build_object('applied', true);
  end if;

  if exists (
    select 1 from public.enrollment_change_requests
    where user_profile_id = p_profile_id
      and academic_year_id = p_academic_year_id
      and status = 'pending'
  ) then
    raise exception 'A change for this school year is already waiting for admin approval.';
  end if;

  select e.status into v_previous
  from public.student_enrollments e
  where e.user_profile_id = p_profile_id and e.academic_year_id = p_academic_year_id;

  select lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix)
    into v_student
    from public."usersData" u where u.id = p_profile_id;

  insert into public.enrollment_change_requests
    (user_profile_id, academic_year_id, requested_status, previous_status, requested_by)
  values
    (p_profile_id, p_academic_year_id, p_status, v_previous, v_staff);

  perform lirc_private.notify_admins(
    'approval_request',
    'Validation change request',
    format('%s — %s: change to %s', v_student, v_year, replace(p_status, '_', ' ')),
    '/enrollments');
  return jsonb_build_object('applied', false);
end $$;

-- public.lirc_review_enrollment_change
create or replace function public.lirc_review_enrollment_change(
  p_request_id bigint, p_approve boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  r record;
  v_admin bigint;
  v_student text;
  v_year text;
begin
  if not lirc_private.is_admin() then
    raise exception 'Only an admin can review change requests.' using errcode = '42501';
  end if;
  v_admin := lirc_private.my_profile_id();
  select * into r from public.enrollment_change_requests
   where id = p_request_id
   for update;
  if not found then raise exception 'Request not found.'; end if;
  if r.status <> 'pending' then raise exception 'This request was already reviewed.'; end if;

  select lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix)
    into v_student from public."usersData" u where u.id = r.user_profile_id;
  select ay.name into v_year
    from public.academic_years ay where ay.id = r.academic_year_id;

  if p_approve then
    perform lirc_private.apply_enrollment_change(r.user_profile_id, r.academic_year_id, r.requested_status);
  end if;

  update public.enrollment_change_requests
     set status = case when p_approve then 'approved' else 'rejected' end,
         reviewed_by = v_admin,
         reviewed_at = now()
   where id = p_request_id;

  perform lirc_private.notify_profile(
    r.requested_by,
    'approval_result',
    case when p_approve then 'Validation change approved' else 'Validation change rejected' end,
    format('%s — %s: %s', v_student, v_year,
      case when p_approve
           then 'now saved as ' || replace(r.requested_status, '_', ' ')
           else 'change to ' || replace(r.requested_status, '_', ' ') || ' was rejected' end),
    '/enrollments');

  return jsonb_build_object('ok', true, 'approved', p_approve);
end $$;

-- public.lirc_borrow_preview
create or replace function public.lirc_borrow_preview(p_library_id text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_card text;
  u public."usersData"%ROWTYPE;
  v_active_year_id bigint;
  v_year_starts date;
  v_year_ends date;
  e public.student_enrollments%ROWTYPE;
  v_active int;
  v_overdue int;
  v_overdue_text text;
  v_required boolean := false;
  v_ok boolean := true;
  v_reason text := '';
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  v_card := btrim(p_library_id);
  if v_card ~ '^\*.*\*$' and length(v_card) > 2 then
    v_card := substr(v_card, 2, length(v_card) - 2);
  end if;
  if v_card = '' or length(v_card) > 120 then
    raise exception 'Enter a valid library card.';
  end if;

  select * into u from public."usersData" where library_id = v_card;
  if not found then raise exception 'Library card not found.'; end if;

  select ay.id, ay.starts_on, ay.ends_on
    into v_active_year_id, v_year_starts, v_year_ends
  from public.semesters s
  join public.academic_years ay on ay.id = s.academic_year_id
  where s.is_active
  limit 1;

  if lower(btrim(u.role::text)) = 'student' and v_active_year_id is not null then
    v_required := true;
    select * into e from public.student_enrollments
    where user_profile_id = u.id and academic_year_id = v_active_year_id;
    if not found then
      v_ok := false;
      v_reason := 'Student has no annual validation for the current school year.';
    elsif e.status <> 'enrolled' or e.validated_at is null
          or e.year_level is null or e.year_level not between 1 and 4 then
      v_ok := false;
      v_reason := format('Student is not validated as enrolled (status: %).', e.status);
    end if;
  end if;

  select count(*) filter (where l.returned_at is null),
         count(*) filter (where l.returned_at is null and l.due_at < now())
    into v_active, v_overdue
  from public.book_loans l
  where l.user_profile_id = u.id;

  select string_agg(x.item, ', ') into v_overdue_text
  from (
    select b.book_name
             || ' (due '
             || to_char(l.due_at at time zone 'Asia/Manila', 'Mon DD')
             || ')' as item
    from public.book_loans l
    join public.book_accession_numbers a on a.id = l.accession_id
    join public.books b on b.id = a.book_id
    where l.user_profile_id = u.id
      and l.returned_at is null
      and l.due_at < now()
    order by l.due_at
    limit 3
  ) x;

  return jsonb_build_object(
    'profile', jsonb_build_object(
      'id', u.id,
      'full_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
      'library_id', u.library_id,
      'role', u.role),
    'student_check', jsonb_build_object(
      'required', v_required,
      'ok', v_ok,
      'reason', v_reason,
      'year_starts', v_year_starts,
      'year_ends', v_year_ends),
    'active_loans', coalesce(v_active, 0),
    'overdue_loans', coalesce(v_overdue, 0),
    'overdue_text', coalesce(v_overdue_text, ''));
end $$;

-- public.lirc_book_loans
create or replace function public.lirc_book_loans(p_book_id bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare result jsonb;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  select jsonb_build_object('loans', coalesce(jsonb_agg(jsonb_build_object(
      'id', x.loan_id,
      'accession_id', x.accession_id,
      'accession_number', x.accession_number,
      'holder', x.holder,
      'library_id', x.member_card,
      'role', x.member_role,
      'borrowed_at', x.borrowed_at,
      'due_at', x.due_at,
      'returned_at', x.returned_at,
      'is_open', x.is_open,
      'is_overdue', x.is_overdue
    ) order by x.borrowed_at desc, x.loan_id desc), '[]'::jsonb))
  into result
  from (
    select l.id as loan_id, a.id as accession_id, a.accession_number,
      lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as holder,
      u.library_id as member_card, u.role as member_role,
      l.borrowed_at, l.due_at, l.returned_at,
      l.returned_at is null as is_open,
      (l.returned_at is null and l.due_at < now()) as is_overdue
    from public.book_loans l
    join public.book_accession_numbers a on a.id = l.accession_id
    join public."usersData" u on u.id = l.user_profile_id
    where a.book_id = p_book_id
    order by l.borrowed_at desc, l.id desc
    limit 100
  ) x;
  return result;
end $$;

-- public.lirc_member_lookup
create or replace function public.lirc_member_lookup(p_search text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_search text;
  v_words text[];
  result jsonb;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  v_search := btrim(coalesce(p_search, ''));
  if v_search = '' or length(v_search) > 120 then
    raise exception 'Type a name or library card.';
  end if;

  select coalesce(array_agg(w), '{}') into v_words
  from unnest(regexp_split_to_array(lower(v_search), '\s+')) as w
  where w <> '';

  -- 1) Exact card, or every word appears somewhere in the name (any order).
  select jsonb_build_object('members', coalesce(jsonb_agg(jsonb_build_object(
      'id', x.id,
      'full_name', x.full_name,
      'library_id', x.library_id,
      'role', x.role,
      'active_loans', x.active_loans,
      'overdue_loans', x.overdue_loans
    ) order by x.surname, x.id), '[]'::jsonb))
  into result
  from (
    select u.id,
      lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as full_name,
      u.library_id, u.role, u.surname,
      (select count(*) from public.book_loans l
        where l.user_profile_id = u.id and l.returned_at is null) as active_loans,
      (select count(*) from public.book_loans l
        where l.user_profile_id = u.id and l.returned_at is null and l.due_at < now()) as overdue_loans
    from public."usersData" u
    where lower(u.library_id) = lower(v_search)
       or not exists (
         select 1 from unnest(v_words) as w
         where lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix)
               not ilike '%' || w || '%'
       )
    order by u.surname, u.id
    limit 10
  ) x;

  -- 2) Nothing found: try similar names (typos, spelling variants).
  if result->'members' = '[]'::jsonb then
    select jsonb_build_object('members', coalesce(jsonb_agg(jsonb_build_object(
        'id', x.id,
        'full_name', x.full_name,
        'library_id', x.library_id,
        'role', x.role,
        'active_loans', x.active_loans,
        'overdue_loans', x.overdue_loans
      ) order by x.similarity desc, x.surname, x.id), '[]'::jsonb))
    into result
    from (
      select u.id,
        lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as full_name,
        u.library_id, u.role, u.surname,
        extensions.word_similarity(
          lower(v_search),
          lower(concat_ws(' ', u.first_name, u.middle_initial, u.surname, u.suffix))) as similarity,
        (select count(*) from public.book_loans l
          where l.user_profile_id = u.id and l.returned_at is null) as active_loans,
        (select count(*) from public.book_loans l
          where l.user_profile_id = u.id and l.returned_at is null and l.due_at < now()) as overdue_loans
      from public."usersData" u
      where extensions.word_similarity(
              lower(v_search),
              lower(concat_ws(' ', u.first_name, u.middle_initial, u.surname, u.suffix))) > 0.6
      order by similarity desc, u.surname, u.id
      limit 10
    ) x;
  end if;

  return result;
end $$;

-- public.lirc_member_profile
create or replace function public.lirc_member_profile(p_profile_id bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare result jsonb;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'id', u.id,
    'full_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
    'first_name', u.first_name,
    'surname', u.surname,
    'middle_initial', u.middle_initial,
    'suffix', u.suffix,
    'library_id', u.library_id,
    'role', u.role,
    'user_linked', u.user_id is not null,
    'department_id', u.department_id,
    'program_id', u.program_id,
    'position_classification_id', u.position_classification_id,
    'department', d.name,
    'program', p.name,
    'position', pc.name,
    'active_loans', (select count(*) from public.book_loans l
      where l.user_profile_id = u.id and l.returned_at is null),
    'overdue_loans', (select count(*) from public.book_loans l
      where l.user_profile_id = u.id and l.returned_at is null and l.due_at < now()),
    'visits', (select count(*) from public.attendance a
      where a.user_profile_id = u.id))
  into result
  from public."usersData" u
  left join public.departments d on d.id = u.department_id
  left join public.programs p on p.id = u.program_id
  left join public.position_classifications pc on pc.id = u.position_classification_id
  where u.id = p_profile_id;
  if result is null then raise exception 'Library member not found.'; end if;
  return result;
end $$;

-- public.lirc_request_member_change
create or replace function public.lirc_request_member_change(
  p_profile_id bigint, p_changes jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_operator bigint;
  v_changes jsonb;
  v_previous jsonb;
  v_member text;
  v_card text;
  v_id bigint;
begin
  v_operator := lirc_private.library_operator_id();
  if v_operator is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  v_changes := lirc_private.sanitize_member_changes(p_changes, p_profile_id);
  if v_changes = '{}'::jsonb then
    raise exception 'Nothing changed.';
  end if;

  select lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix), u.library_id,
         jsonb_build_object(
           'first_name', u.first_name, 'surname', u.surname,
           'middle_initial', u.middle_initial, 'suffix', u.suffix,
           'department_id', u.department_id, 'program_id', u.program_id,
           'position_classification_id', u.position_classification_id)
    into v_member, v_card, v_previous
  from public."usersData" u where u.id = p_profile_id;

  -- Admins are the approvers: their edits apply immediately.
  if lirc_private.is_admin() then
    perform lirc_private.apply_member_change(p_profile_id, v_changes);
    return jsonb_build_object('applied', true);
  end if;

  if exists (
    select 1 from public.member_change_requests
    where user_profile_id = p_profile_id and status = 'pending'
  ) then
    raise exception 'An edit for this member is already waiting for admin approval.';
  end if;

  insert into public.member_change_requests
    (user_profile_id, requested_changes, previous_values, requested_by)
  values (p_profile_id, v_changes, v_previous, v_operator)
  returning id into v_id;

  perform lirc_private.notify_admins(
    'member_edit_request',
    'Member edit request',
    format('%s (%s) — profile edit waiting for approval', v_member, v_card),
    '/users?request=' || v_id);

  return jsonb_build_object('applied', false, 'request_id', v_id);
end $$;

-- public.lirc_member_change_requests
create or replace function public.lirc_member_change_requests(
  p_only_mine boolean default false)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_operator bigint;
  result jsonb;
begin
  v_operator := lirc_private.library_operator_id();
  if v_operator is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  if not p_only_mine and not lirc_private.is_admin() then
    raise exception 'Admin access required.' using errcode = '42501';
  end if;
  select jsonb_build_object('requests', coalesce(jsonb_agg(jsonb_build_object(
      'id', x.id,
      'member', x.member,
      'member_card', x.member_card,
      'requested_changes', x.requested_changes,
      'previous_values', x.previous_values,
      'requested_by', x.requested_by,
      'status', x.status,
      'reviewed_by', x.reviewed_by,
      'reviewed_at', x.reviewed_at,
      'created_at', x.created_at
    ) order by x.created_at desc, x.id desc), '[]'::jsonb))
  into result
  from (
    select r.id,
      lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as member,
      u.library_id as member_card,
      r.requested_changes, r.previous_values,
      lirc_private.person_name(rb.first_name, rb.middle_initial, rb.surname, rb.suffix) as requested_by,
      r.status,
      nullif(lirc_private.person_name(rv.first_name, rv.middle_initial, rv.surname, rv.suffix), '') as reviewed_by,
      r.reviewed_at, r.created_at
    from public.member_change_requests r
    join public."usersData" u on u.id = r.user_profile_id
    join public."usersData" rb on rb.id = r.requested_by
    left join public."usersData" rv on rv.id = r.reviewed_by
    where not p_only_mine or r.requested_by = v_operator
    order by r.created_at desc, r.id desc
    limit 100
  ) x;
  return result;
end $$;

-- public.lirc_return_loan
create or replace function public.lirc_return_loan(
  p_loan_id bigint,
  p_library_id text,
  p_returned_at timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_operator bigint;
  l public.book_loans%ROWTYPE;
  v_card text;
  u public."usersData"%ROWTYPE;
  v_borrower text;
  v_returned timestamptz;
begin
  v_operator := lirc_private.library_operator_id();
  if v_operator is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;

  v_card := btrim(p_library_id);
  if v_card ~ '^\*.*\*$' and length(v_card) > 2 then
    v_card := substr(v_card, 2, length(v_card) - 2);
  end if;
  if v_card = '' or length(v_card) > 120 then
    raise exception 'Scan the borrower''s library card.';
  end if;

  select * into l from public.book_loans where id = p_loan_id for update;
  if not found then raise exception 'Loan not found.'; end if;
  if l.returned_at is not null then raise exception 'This loan is already returned.'; end if;

  select * into u from public."usersData" where library_id = v_card;
  if not found then raise exception 'Library card not found.'; end if;
  if u.id <> l.user_profile_id then
    select lirc_private.person_name(b.first_name, b.middle_initial, b.surname, b.suffix)
      into v_borrower
      from public."usersData" b
     where b.id = l.user_profile_id;
    raise exception 'This copy was borrowed by %. Only the borrower''s card can return it.', v_borrower;
  end if;

  v_returned := coalesce(p_returned_at, now());
  if v_returned < l.borrowed_at then
    raise exception 'The return date/time cannot be before the start.';
  end if;
  if v_returned > now() + interval '1 day' then
    raise exception 'The return date/time cannot be in the future.';
  end if;

  update public.book_loans
     set returned_at = v_returned, returned_by = v_operator
   where id = p_loan_id;
  return jsonb_build_object('ok', true);
end $$;

-- lirc_private.inventory_session_json
create or replace function lirc_private.inventory_session_json(p_session_id bigint)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'id', s.id,
    'name', s.name,
    'year', s.year,
    'status', s.status,
    'summary', s.summary,
    'created_at', s.created_at,
    'created_by', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
    'finished_at', s.finished_at,
    'finished_by', lirc_private.person_name(f.first_name, f.middle_initial, f.surname, f.suffix),
    'paused_at', s.paused_at,
    'paused_by', lirc_private.person_name(pb.first_name, pb.middle_initial, pb.surname, pb.suffix))
  from public.inventory_sessions s
  join public."usersData" u on u.id = s.created_by
  left join public."usersData" f on f.id = s.finished_by
  left join public."usersData" pb on pb.id = s.paused_by
  where s.id = p_session_id;
$$;

-- lirc_private.inventory_entry_json
create or replace function lirc_private.inventory_entry_json(p_entry_id bigint)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'id', e.id,
    'session_id', e.session_id,
    'accession_id', e.accession_id,
    'accession_number', a.accession_number,
    'book_id', b.id,
    'book_name', b.book_name,
