-- public.lirc_barcode_queue
create or replace function public.lirc_barcode_queue(
  p_limit integer default 25,
  p_offset integer default 0)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_limit integer;
  v_offset integer;
  v_total bigint;
  v_rows jsonb;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  v_limit := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_offset := greatest(coalesce(p_offset, 0), 0);

  select count(*) into v_total
  from public.barcode_entries e
  where e.template_id is null;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', x.id,
      'accession_number', x.accession_number,
      'added_at', x.added_at,
      'added_by', x.added_by) order by x.added_at desc, x.id desc), '[]'::jsonb)
    into v_rows
  from (
    select e.id, e.accession_number, e.added_at,
           lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as added_by
    from public.barcode_entries e
    join public."usersData" u on u.id = e.added_by
    where e.template_id is null
    order by e.added_at desc, e.id desc
    limit v_limit offset v_offset
  ) x;

  return jsonb_build_object(
    'rows', v_rows,
    'total', v_total,
    'has_next', (v_offset + v_limit) < v_total);
end $$;

-- public.lirc_activity_feed
create or replace function public.lirc_activity_feed(
  p_scope text default 'own',
  p_filters jsonb default '{}'::jsonb,
  p_before_occurred_at timestamptz default null,
  p_before_id bigint default null,
  p_page_size integer default 25)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me bigint := lirc_private.my_profile_id();
  v_scope text := coalesce(lower(btrim(coalesce(p_scope, 'own'))), 'own');
  v_limit integer := least(greatest(coalesce(p_page_size, 25), 1), 100);
  v_rows jsonb;
  v_has_more boolean := false;
  v_next_time timestamptz;
  v_next_id bigint;
  v_action text;
  v_prefix text;
  v_prefixes text[];
  v_entity_type text;
  v_entity_id bigint;
  v_source text;
  v_from timestamptz;
  v_to timestamptz;
begin
  if v_me is null then
    raise exception 'No library profile for this account.' using errcode = '42501';
  end if;
  if v_scope not in ('own', 'all') then
    raise exception 'Unknown scope.';
  end if;
  if v_scope = 'all' and not lirc_private.is_admin() then
    raise exception 'Admin access required.' using errcode = '42501';
  end if;

  v_action := nullif(p_filters ->> 'action', '');
  v_prefix := nullif(p_filters ->> 'action_prefix', '');
  v_prefixes := case
    when jsonb_typeof(p_filters -> 'action_prefixes') = 'array'
      then (select array_agg(value || '%')
              from jsonb_array_elements_text(p_filters -> 'action_prefixes'))
    else null end;
  v_entity_type := nullif(p_filters ->> 'entity_type', '');
  v_entity_id := nullif(p_filters ->> 'entity_id', '')::bigint;
  v_source := nullif(p_filters ->> 'source', '');
  v_from := nullif(p_filters ->> 'from_occurred_at', '')::timestamptz;
  v_to := nullif(p_filters ->> 'to_occurred_at', '')::timestamptz;

  with base as (
    select e.*
    from public.activity_events e
    where (v_scope = 'all' or e.actor_profile_id = v_me)
      and (v_action is null or e.action = v_action)
      and (v_prefix is null or e.action like v_prefix || '%')
      and (v_prefixes is null or e.action like any (v_prefixes))
      and (v_entity_type is null or e.entity_type = v_entity_type)
      and (v_entity_id is null or e.entity_id = v_entity_id)
      and (v_source is null or e.source = v_source)
      and (v_from is null or e.occurred_at >= v_from)
      and (v_to is null or e.occurred_at < v_to)
      and (p_before_occurred_at is null
           or (e.occurred_at, e.id) < (p_before_occurred_at, coalesce(p_before_id, 0)))
    order by e.occurred_at desc, e.id desc
    limit v_limit + 1
  ),
  page as (
    select * from base order by occurred_at desc, id desc limit v_limit
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id,
      'occurred_at', p.occurred_at,
      'action', p.action,
      'source', p.source,
      'actor_kind', p.actor_kind,
      'actor_profile_id', p.actor_profile_id,
      'actor_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
      'actor_role', p.actor_role,
      'entity_type', p.entity_type,
      'entity_id', p.entity_id,
      'operation_id', p.operation_id,
      'parent_type', p.parent_type,
      'parent_id', p.parent_id,
      'changes', p.changes,
      'reason', p.reason,
      'description', lirc_private.describe_activity(p))
      order by p.occurred_at desc, p.id desc), '[]'::jsonb),
    (select count(*) from base) > (select count(*) from page),
    (select p.occurred_at from page p order by p.occurred_at asc, p.id asc limit 1),
    (select p.id from page p order by p.occurred_at asc, p.id asc limit 1)
  into v_rows, v_has_more, v_next_time, v_next_id
  from page p
  left join public."usersData" u on u.id = p.actor_profile_id;

  return jsonb_build_object(
    'rows', v_rows,
    'has_more', coalesce(v_has_more, false),
    'next_before_occurred_at', case when v_has_more then v_next_time end,
    'next_before_id', case when v_has_more then v_next_id end);
end $$;

-- public.lirc_activity_for_entity
create or replace function public.lirc_activity_for_entity(
  p_entity_type text,
  p_entity_id bigint,
  p_before_occurred_at timestamptz default null,
  p_before_id bigint default null,
  p_page_size integer default 25)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me bigint := lirc_private.my_profile_id();
  v_admin boolean := lirc_private.is_admin();
  v_limit integer := least(greatest(coalesce(p_page_size, 25), 1), 100);
  v_type text := btrim(coalesce(p_entity_type, ''));
  v_rows jsonb;
  v_has_more boolean := false;
  v_next_time timestamptz;
  v_next_id bigint;
begin
  if v_me is null then
    raise exception 'No library profile for this account.' using errcode = '42501';
  end if;
  if v_type = '' or p_entity_id is null then
    raise exception 'A record type and id are required.';
  end if;

  with base as (
    select e.*
    from public.activity_events e
    where e.entity_type = v_type
      and e.entity_id = p_entity_id
      and (v_admin or e.actor_profile_id = v_me)
      and (p_before_occurred_at is null
           or (e.occurred_at, e.id) < (p_before_occurred_at, coalesce(p_before_id, 0)))
    order by e.occurred_at desc, e.id desc
    limit v_limit + 1
  ),
  page as (
    select * from base order by occurred_at desc, id desc limit v_limit
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id,
      'occurred_at', p.occurred_at,
      'action', p.action,
      'source', p.source,
      'actor_profile_id', p.actor_profile_id,
      'actor_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
      'changes', p.changes,
      'description', lirc_private.describe_activity(p))
      order by p.occurred_at desc, p.id desc), '[]'::jsonb),
    (select count(*) from base) > (select count(*) from page),
    (select p.occurred_at from page p order by p.occurred_at asc, p.id asc limit 1),
    (select p.id from page p order by p.occurred_at asc, p.id asc limit 1)
  into v_rows, v_has_more, v_next_time, v_next_id
  from page p
  left join public."usersData" u on u.id = p.actor_profile_id;

  return jsonb_build_object(
    'rows', v_rows,
    'has_more', coalesce(v_has_more, false),
    'next_before_occurred_at', case when v_has_more then v_next_time end,
    'next_before_id', case when v_has_more then v_next_id end);
end $$;

-- public.lirc_sign_in_activity
create or replace function public.lirc_sign_in_activity(
  p_scope text default 'own',
  p_page_size integer default 10)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me bigint := lirc_private.my_profile_id();
  v_uid uuid;
  v_scope text := lower(btrim(coalesce(p_scope, 'own')));
  v_limit integer := least(greatest(coalesce(p_page_size, 10), 1), 50);
  v_audit_rows integer;
  v_rows jsonb;
  v_source text;
  v_total bigint;
  v_first timestamptz;
  v_last timestamptz;
begin
  if v_me is null then
    raise exception 'No library profile for this account.' using errcode = '42501';
  end if;
  if v_scope not in ('own', 'all') then
    raise exception 'Unknown scope.';
  end if;
  if v_scope = 'all' and not lirc_private.is_admin() then
    raise exception 'Admin access required.' using errcode = '42501';
  end if;
  select u.user_id into v_uid from public."usersData" u where u.id = v_me;

  select count(*) into v_audit_rows
  from auth.audit_log_entries al
  where al.payload ->> 'action' in ('login', 'logout')
    and (v_scope = 'all' or al.payload ->> 'actor_id' = v_uid::text);

  if v_audit_rows > 0 then
    v_source := 'audit';
    select count(*), min(al.created_at), max(al.created_at)
      into v_total, v_first, v_last
    from auth.audit_log_entries al
    where al.payload ->> 'action' in ('login', 'logout')
      and (v_scope = 'all' or al.payload ->> 'actor_id' = v_uid::text);
    select coalesce(jsonb_agg(jsonb_build_object(
      'occurred_at', x.created_at,
      'action', case x.act when 'login' then 'Signed in'
                           when 'logout' then 'Signed out'
                           else x.act end,
      'actor_profile_id', u.id,
      'actor_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
      'actor_role', u.role,
      'detail', x.actor_name)
      order by x.created_at desc), '[]'::jsonb)
    into v_rows
    from (
      select al.created_at,
             al.payload ->> 'action' as act,
             al.payload ->> 'actor_username' as actor_name,
             al.payload ->> 'actor_id' as actor_id
      from auth.audit_log_entries al
      where al.payload ->> 'action' in ('login', 'logout')
        and (v_scope = 'all' or al.payload ->> 'actor_id' = v_uid::text)
      order by al.created_at desc
      limit v_limit
    ) x
    left join public."usersData" u on u.user_id::text = x.actor_id;
  else
    v_source := 'sessions';
    select count(*), min(s.created_at), max(s.created_at)
      into v_total, v_first, v_last
    from auth.sessions s
    where v_scope = 'all' or s.user_id = v_uid;
    select coalesce(jsonb_agg(jsonb_build_object(
      'occurred_at', x.created_at,
      'action', 'Session started',
      'actor_profile_id', u.id,
      'actor_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
      'actor_role', u.role,
      'detail', x.user_agent)
      order by x.created_at desc), '[]'::jsonb)
    into v_rows
    from (
      select s.created_at, s.user_id, s.user_agent
      from auth.sessions s
      where v_scope = 'all' or s.user_id = v_uid
      order by s.created_at desc
      limit v_limit
    ) x
    left join public."usersData" u on u.user_id = x.user_id;
  end if;

  return jsonb_build_object(
    'source', v_source,
    'scope', v_scope,
    'rows', v_rows,
    'total', coalesce(v_total, 0),
    'coverage_first', v_first,
    'coverage_last', v_last,
    'note', case
      when v_source = 'audit'
        then 'From the Supabase auth audit log (logins and logouts).'
      else 'From session records only — sign-outs and denied attempts appear once "Write audit logs to the database" is enabled in the Supabase dashboard.'
    end);
end $$;

-- public.lirc_activity_log_page
create or replace function public.lirc_activity_log_page(
  p_filters jsonb default '{}'::jsonb,
  p_page integer default 1,
  p_page_size integer default 25)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_size integer := least(greatest(coalesce(p_page_size, 25), 1), 100);
  v_prefix text := nullif(btrim(coalesce(p_filters ->> 'action_prefix', '')), '');
  v_prefixes text[] := case
    when jsonb_typeof(p_filters -> 'action_prefixes') = 'array'
      then (select array_agg(value || '%')
              from jsonb_array_elements_text(p_filters -> 'action_prefixes'))
    else null end;
  v_role text := nullif(btrim(coalesce(p_filters ->> 'actor_role', '')), '');
  v_source text := nullif(btrim(coalesce(p_filters ->> 'source', '')), '');
  v_actor_search text := nullif(btrim(coalesce(p_filters ->> 'actor_search', '')), '');
  v_words text[];
  v_from timestamptz := nullif(p_filters ->> 'from_occurred_at', '')::timestamptz;
  v_to timestamptz := nullif(p_filters ->> 'to_occurred_at', '')::timestamptz;
  v_total bigint;
  v_rows jsonb;
begin
  if not lirc_private.is_admin() then
    raise exception 'Admin access required.' using errcode = '42501';
  end if;
  if v_actor_search is not null then
    if char_length(v_actor_search) > 120 then
      v_actor_search := left(v_actor_search, 120);
    end if;
    v_words := regexp_split_to_array(lower(v_actor_search), '\s+');
  end if;

  select count(*) into v_total
  from public.activity_events e
  where (v_prefix is null or e.action like v_prefix || '%')
    and (v_prefixes is null or e.action like any (v_prefixes))
    and (v_role is null
         or coalesce(
              (select u.role::text from public."usersData" u
                where u.id = e.actor_profile_id),
              e.actor_role) = v_role)
    and (v_source is null or e.source = v_source)
    and (v_from is null or e.occurred_at >= v_from)
    and (v_to is null or e.occurred_at < v_to)
    and (v_actor_search is null or exists (
      select 1
      from public."usersData" u
      where u.id = e.actor_profile_id
        and (
          not exists (
            select 1 from unnest(v_words) as w
            where w <> ''
              and lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) not ilike '%' || w || '%')
          or extensions.word_similarity(
               lower(v_actor_search),
               lower(concat_ws(' ', u.first_name, u.middle_initial,
                               u.surname, u.suffix))) > 0.6)));

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', y.id,
    'occurred_at', y.occurred_at,
    'action', y.action,
    'source', y.source,
    'actor_kind', y.actor_kind,
    'actor_profile_id', y.actor_profile_id,
    'actor_name', (
      select lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix)
      from public."usersData" u where u.id = y.actor_profile_id),
    'actor_role', coalesce(
      (select u.role::text from public."usersData" u
        where u.id = y.actor_profile_id),
      y.actor_role),
    'entity_type', y.entity_type,
    'entity_id', y.entity_id,
    'operation_id', y.operation_id,
    'changes', y.changes,
    'reason', y.reason,
    'description', lirc_private.describe_activity(y))
    order by y.occurred_at desc, y.id desc), '[]'::jsonb)
  into v_rows
  from (
    select e.*
    from public.activity_events e
    where (v_prefix is null or e.action like v_prefix || '%')
      and (v_prefixes is null or e.action like any (v_prefixes))
      and (v_role is null
           or coalesce(
                (select u.role::text from public."usersData" u
                  where u.id = e.actor_profile_id),
                e.actor_role) = v_role)
      and (v_source is null or e.source = v_source)
      and (v_from is null or e.occurred_at >= v_from)
      and (v_to is null or e.occurred_at < v_to)
      and (v_actor_search is null or exists (
        select 1
        from public."usersData" u
        where u.id = e.actor_profile_id
          and (
            not exists (
              select 1 from unnest(v_words) as w
              where w <> ''
                and lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) not ilike '%' || w || '%')
            or extensions.word_similarity(
                 lower(v_actor_search),
                 lower(concat_ws(' ', u.first_name, u.middle_initial,
                                 u.surname, u.suffix))) > 0.6)))
    order by e.occurred_at desc, e.id desc
    limit v_size offset (v_page - 1) * v_size
  ) y;

  return jsonb_build_object(
    'rows', v_rows,
    'total', v_total,
    'page', v_page,
    'page_size', v_size,
    'pages', greatest(ceil(v_total::numeric / v_size), 1),
    'has_prev', v_page > 1,
    'has_next', (v_page * v_size) < v_total);
end $$;

-- public.lirc_personnel_performance_people
create or replace function public.lirc_personnel_performance_people()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_rows jsonb;
begin
  if not lirc_private.is_admin() then
    raise exception 'Admin access required.' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', u.id,
           'full_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
           'role', u.role,
           'library_id', u.library_id)
         order by case lower(btrim(u.role::text))
                    when 'librarian' then 1
                    when 'staff' then 2
                    else 3
                  end,
                  u.surname, u.first_name, u.id), '[]'::jsonb)
    into v_rows
  from public."usersData" u
  where lower(btrim(u.role::text)) in ('librarian', 'staff', 'admin');
  return v_rows;
end $$;

-- public.lirc_personnel_performance
create or replace function public.lirc_personnel_performance(
  p_profile_id bigint, p_days integer default 30)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  u public."usersData"%ROWTYPE;
  v_last timestamptz;
begin
  if not lirc_private.is_admin() then
    raise exception 'Admin access required.' using errcode = '42501';
  end if;
  select * into u from public."usersData" where id = p_profile_id;
  if not found then
    raise exception 'Person not found.';
  end if;
  if lower(btrim(u.role::text)) not in ('librarian', 'staff', 'admin') then
    raise exception 'Not a library personnel record.';
  end if;
  select max(e.occurred_at) into v_last
  from public.activity_events e
  where e.actor_profile_id = u.id;
  return jsonb_build_object(
    'profile', jsonb_build_object(
      'id', u.id,
      'full_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
      'role', u.role,
      'library_id', u.library_id),
    'last_active_at', v_last,
    'summary', lirc_private.activity_summary_for(u.id, p_days));
end $$;

-- public.lirc_enrollment_requests
create or replace function public.lirc_enrollment_requests(
  p_only_mine boolean default false)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_operator bigint;
  result jsonb;
begin
  v_operator := lirc_private.library_operator_id();
  if v_operator is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  if not p_only_mine and not lirc_private.is_admin() then
    raise exception 'Admin access required.' using errcode = '42501';
  end if;
  select jsonb_build_object('requests', coalesce(jsonb_agg(jsonb_build_object(
      'id', x.id,
      'student', x.student,
      'student_card', x.student_card,
      'year_name', x.year_name,
      'requested_status', x.requested_status,
      'previous_status', x.previous_status,
      'requested_by', x.requested_by,
      'status', x.status,
      'reviewed_by', x.reviewed_by,
      'reviewed_at', x.reviewed_at,
      'created_at', x.created_at
    ) order by x.created_at desc, x.id desc), '[]'::jsonb))
  into result
  from (
    select r.id,
      lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as student,
      u.library_id as student_card,
      ay.name as year_name,
      r.requested_status, r.previous_status,
      lirc_private.person_name(rb.first_name, rb.middle_initial, rb.surname, rb.suffix) as requested_by,
      r.status,
      nullif(lirc_private.person_name(rv.first_name, rv.middle_initial, rv.surname, rv.suffix), '') as reviewed_by,
      r.reviewed_at, r.created_at
    from public.enrollment_change_requests r
    join public."usersData" u on u.id = r.user_profile_id
    join public.academic_years ay on ay.id = r.academic_year_id
    join public."usersData" rb on rb.id = r.requested_by
    left join public."usersData" rv on rv.id = r.reviewed_by
    where not p_only_mine or r.requested_by = v_operator
    order by r.created_at desc, r.id desc
    limit 100
  ) x;
  return result;
end $$;

-- public.lirc_enrollment_request_detail
create or replace function public.lirc_enrollment_request_detail(
  p_request_id bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  r record;
  u record;
  v_year jsonb;
  v_enrollment jsonb;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  select * into r from public.enrollment_change_requests
   where id = p_request_id;
  if not found then raise exception 'Request not found.'; end if;
  select * into u from public."usersData" where id = r.user_profile_id;
  select jsonb_build_object('id', ay.id, 'name', ay.name)
    into v_year
    from public.academic_years ay where ay.id = r.academic_year_id;
  select jsonb_build_object(
      'id', e.id,
      'status', e.status,
      'year_level', e.year_level,
      'year_level_note', e.year_level_note,
      'validated_at', e.validated_at,
      'validation_reference', e.validation_reference)
    into v_enrollment
    from public.student_enrollments e
    where e.user_profile_id = r.user_profile_id
      and e.academic_year_id = r.academic_year_id;
  return jsonb_build_object(
    'request', jsonb_build_object(
      'id', r.id,
      'status', r.status,
      'requested_status', r.requested_status,
      'previous_status', r.previous_status,
      'created_at', r.created_at),
    'profile', jsonb_build_object(
      'id', u.id,
      'first_name', u.first_name,
      'middle_initial', u.middle_initial,
      'surname', u.surname,
      'suffix', u.suffix,
      'full_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
      'library_id', u.library_id,
      'role', u.role),
    'year', v_year,
    'enrollment', v_enrollment);
end $$;

-- public.lirc_sign_in_activity
create or replace function public.lirc_sign_in_activity(
  p_scope text default 'own',
  p_page_size integer default 10,
  p_offset integer default 0)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me bigint := lirc_private.my_profile_id();
  v_uid uuid;
  v_scope text := lower(btrim(coalesce(p_scope, 'own')));
  v_limit integer := least(greatest(coalesce(p_page_size, 10), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_audit_rows integer;
  v_rows jsonb;
  v_source text;
  v_total bigint;
  v_first timestamptz;
  v_last timestamptz;
begin
  if v_me is null then
    raise exception 'No library profile for this account.' using errcode = '42501';
  end if;
  if v_scope not in ('own', 'all') then
    raise exception 'Unknown scope.';
  end if;
  if v_scope = 'all' and not lirc_private.is_admin() then
    raise exception 'Admin access required.' using errcode = '42501';
  end if;
  select u.user_id into v_uid from public."usersData" u where u.id = v_me;

  select count(*) into v_audit_rows
  from auth.audit_log_entries al
  where al.payload ->> 'action' in ('login', 'logout')
    and (v_scope = 'all' or al.payload ->> 'actor_id' = v_uid::text);

  if v_audit_rows > 0 then
    v_source := 'audit';
    select count(*), min(al.created_at), max(al.created_at)
      into v_total, v_first, v_last
    from auth.audit_log_entries al
    where al.payload ->> 'action' in ('login', 'logout')
      and (v_scope = 'all' or al.payload ->> 'actor_id' = v_uid::text);
    select coalesce(jsonb_agg(jsonb_build_object(
      'occurred_at', x.created_at,
      'action', case x.act when 'login' then 'Signed in'
                           when 'logout' then 'Signed out'
                           else x.act end,
      'actor_profile_id', u.id,
      'actor_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
      'actor_role', u.role,
      'detail', x.actor_name)
      order by x.created_at desc), '[]'::jsonb)
    into v_rows
    from (
      select al.created_at,
             al.payload ->> 'action' as act,
             al.payload ->> 'actor_username' as actor_name,
             al.payload ->> 'actor_id' as actor_id
      from auth.audit_log_entries al
      where al.payload ->> 'action' in ('login', 'logout')
        and (v_scope = 'all' or al.payload ->> 'actor_id' = v_uid::text)
      order by al.created_at desc
      limit v_limit offset v_offset
    ) x
    left join public."usersData" u on u.user_id::text = x.actor_id;
  else
    v_source := 'sessions';
    select count(*), min(s.created_at), max(s.created_at)
      into v_total, v_first, v_last
    from auth.sessions s
    where v_scope = 'all' or s.user_id = v_uid;
    select coalesce(jsonb_agg(jsonb_build_object(
      'occurred_at', x.created_at,
      'action', 'Session started',
      'actor_profile_id', u.id,
      'actor_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
      'actor_role', u.role,
      'detail', x.user_agent)
      order by x.created_at desc), '[]'::jsonb)
    into v_rows
    from (
      select s.created_at, s.user_id, s.user_agent
      from auth.sessions s
      where v_scope = 'all' or s.user_id = v_uid
      order by s.created_at desc
      limit v_limit offset v_offset
    ) x
    left join public."usersData" u on u.user_id = x.user_id;
  end if;

  return jsonb_build_object(
    'source', v_source,
    'scope', v_scope,
    'rows', v_rows,
    'total', coalesce(v_total, 0),
    'offset', v_offset,
    'has_more', (v_offset + v_limit) < coalesce(v_total, 0),
    'coverage_first', v_first,
    'coverage_last', v_last,
    'note', case
      when v_source = 'audit'
        then 'From the Supabase auth audit log (logins and logouts).'
      else 'From session records only — sign-outs and denied attempts appear once "Write audit logs to the database" is enabled in the Supabase dashboard.'
    end);
end $$;

-- public.lirc_my_profile
create or replace function public.lirc_my_profile()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me bigint := lirc_private.my_profile_id();
  u public."usersData"%ROWTYPE;
begin
  if v_me is null then
    raise exception 'No library profile for this account.' using errcode = '42501';
  end if;
  select * into u from public."usersData" where id = v_me;
  return jsonb_build_object(
    'id', u.id,
    'full_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
    'first_name', u.first_name,
    'middle_initial', u.middle_initial,
    'surname', u.surname,
    'suffix', u.suffix,
    'library_id', u.library_id,
    'role', u.role,
    'avatar_url', u.avatar_url,
    'department', (select d.name from public.departments d where d.id = u.department_id),
    'program', (select p.name from public.programs p where p.id = u.program_id),
    'position', (select pc.name from public.position_classifications pc
                  where pc.id = u.position_classification_id),
    'email', (select au.email from auth.users au where au.id = u.user_id));
end $$;

-- public.lirc_performance_ai_input
create or replace function public.lirc_performance_ai_input(
  p_profile_id bigint,
  p_month date default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_start date;
  v_end date;
  v_from timestamptz;
  v_to timestamptz;
  v_days integer;
  u record;
  v_total bigint;
  v_active integer;
  v_busiest_day date;
  v_busiest_count bigint;
  v_distinct integer;
  v_max_share numeric;
  v_after_hours bigint;
  v_weekend bigint;
  v_reviews bigint;
  v_validations bigint;
  v_kinds jsonb;
  v_top_actions jsonb;
  v_events jsonb;
begin
  v_start := date_trunc('month',
    coalesce(p_month, (now() at time zone 'Asia/Manila')::date))::date;
  v_end := (v_start + interval '1 month')::date;
  v_from := v_start::timestamp at time zone 'Asia/Manila';
  v_to := v_end::timestamp at time zone 'Asia/Manila';
  v_days := (v_end - v_start);

  select u2.id,
         lirc_private.person_name(u2.first_name, u2.middle_initial, u2.surname, u2.suffix) as full_name,
         u2.role,
         u2.library_id,
         (select d.name from public.departments d where d.id = u2.department_id) as department,
         (select p.name from public.programs p where p.id = u2.program_id) as program,
         (select pc.name from public.position_classifications pc
           where pc.id = u2.position_classification_id) as position
    into u
    from public."usersData" u2
   where u2.id = p_profile_id;
  if u.id is null then
    raise exception 'Person not found.';
  end if;

  select count(*),
         count(distinct e.action),
         count(*) filter (where extract(hour from (e.occurred_at at time zone 'Asia/Manila')) < 7
                             or extract(hour from (e.occurred_at at time zone 'Asia/Manila')) >= 19),
         count(*) filter (where extract(isodow from (e.occurred_at at time zone 'Asia/Manila')) >= 6),
         count(*) filter (where e.action in ('member_change.review', 'enrollment.review')),
         count(*) filter (where e.action like 'enrollment.%'
                             or e.action like 'student_enrollments.%')
    into v_total, v_distinct, v_after_hours, v_weekend, v_reviews, v_validations
    from public.activity_events e
   where e.actor_profile_id = p_profile_id
     and e.occurred_at >= v_from and e.occurred_at < v_to;

  select count(*) filter (where n > 0) into v_active
    from (
      select (e.occurred_at at time zone 'Asia/Manila')::date as day, count(*) n
        from public.activity_events e
       where e.actor_profile_id = p_profile_id
         and e.occurred_at >= v_from and e.occurred_at < v_to
       group by 1) d;

  select d.day, d.n into v_busiest_day, v_busiest_count
    from (
      select (e.occurred_at at time zone 'Asia/Manila')::date as day, count(*) n
        from public.activity_events e
       where e.actor_profile_id = p_profile_id
         and e.occurred_at >= v_from and e.occurred_at < v_to
       group by 1
       order by 2 desc, 1 desc
       limit 1) d;

  -- the single most repeated action's share of the month (spam indicator)
  select coalesce(max(s.share), 0) into v_max_share
    from (
      select count(*)::numeric / greatest(v_total, 1) as share
        from public.activity_events e
       where e.actor_profile_id = p_profile_id
         and e.occurred_at >= v_from and e.occurred_at < v_to
       group by e.action) s;

  -- same work families as the dashboard donut
  select coalesce(jsonb_agg(jsonb_build_object('kind', x.kind, 'count', x.n)
                            order by x.n desc), '[]'::jsonb)
    into v_kinds
    from (
      select case
               when e.action like 'inventory.%' then 'inventory'
               when e.action like 'loans.%' or e.action like 'book_loans.%' then 'loans'
               when e.action like 'users.%' or e.action like 'usersData.%' then 'members'
               when e.action like 'member_change.%' then 'member_changes'
               when e.action like 'enrollment.%' or e.action like 'student_enrollments.%' then 'validation'
               when e.action like 'catalog.%' or e.action like 'books.%'
                    or e.action like 'book_accession_numbers.%' then 'catalog'
               when e.action like 'attendance.%' then 'attendance'
               when e.action like 'semesters.%' or e.action like 'academic_years.%' then 'periods'
               when e.action like 'barcode.%' or e.action like 'barcode_entries.%'
                    or e.action like 'barcode_templates.%' then 'barcode'
               else 'other'
             end as kind,
             count(*) as n
        from public.activity_events e
       where e.actor_profile_id = p_profile_id
         and e.occurred_at >= v_from and e.occurred_at < v_to
       group by 1) x;

  select coalesce(jsonb_agg(jsonb_build_object('action', x.action, 'count', x.n)
                            order by x.n desc), '[]'::jsonb)
    into v_top_actions
    from (
      select e.action, count(*) as n
        from public.activity_events e
       where e.actor_profile_id = p_profile_id
         and e.occurred_at >= v_from and e.occurred_at < v_to
       group by 1
       order by 2 desc, 1
       limit 12) x;

  -- a spread sample: up to 4 log sentences per active day, read as plain words
  select coalesce(jsonb_agg(jsonb_build_object('at', x.at, 'what', x.what)
                            order by x.at), '[]'::jsonb)
    into v_events
    from (
      select to_char(e.occurred_at at time zone 'Asia/Manila',
                     'Mon DD, HH12:MI AM') as at,
             lirc_private.describe_activity(e) as what,
             row_number() over (
               partition by (e.occurred_at at time zone 'Asia/Manila')::date
               order by e.occurred_at desc) as rn
        from public.activity_events e
       where e.actor_profile_id = p_profile_id
         and e.occurred_at >= v_from and e.occurred_at < v_to) x
   where x.rn <= 4;

  return jsonb_build_object(
    'profile', jsonb_build_object(
      'name', u.full_name, 'role', u.role, 'library_id', u.library_id,
      'department', u.department, 'program', u.program, 'position', u.position),
    'month', to_char(v_start, 'YYYY-MM'),
    'days_in_month', v_days,
    'totals', jsonb_build_object(
      'actions', v_total, 'active_days', v_active,
      'busiest_day', v_busiest_day, 'busiest_count', v_busiest_count),
    'signals', jsonb_build_object(
      'distinct_action_types', v_distinct,
      'max_single_action_share', round(v_max_share, 2),
      'after_hours_actions', v_after_hours,
      'weekend_actions', v_weekend,
      'review_actions', v_reviews,
      'validation_actions', v_validations),
    'by_kind', v_kinds,
    'top_actions', v_top_actions,
    'events', v_events);
end $$;

-- public.lirc_performance_reports
create or replace function public.lirc_performance_reports(p_profile_id bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  result jsonb;
begin
  if not lirc_private.is_admin() then
    raise exception 'Admin access required.' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', r.id,
           'period_month', r.period_month,
           'rating_score', r.rating_score,
           'rating_label', r.rating_label,
           'headline', r.headline,
           'summary', r.summary,
           'model', r.model,
           'created_at', r.created_at,
           'generated_by', nullif(lirc_private.person_name(gb.first_name, gb.middle_initial, gb.surname, gb.suffix), ''))
         order by r.period_month desc, r.id desc), '[]'::jsonb)
    into result
    from public.performance_reports r
    left join public."usersData" gb on gb.id = r.generated_by
   where r.user_profile_id = p_profile_id;
  return result;
end $$;

-- public.lirc_loan_records
create or replace function public.lirc_loan_records(
  p_scope text default 'borrowed',
  p_filters jsonb default '{}'::jsonb,
  p_page integer default 1,
  p_page_size integer default 20)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_scope text := lower(btrim(coalesce(p_scope, 'borrowed')));
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_size integer := least(greatest(coalesce(p_page_size, 20), 1), 100);
  v_member_search text := nullif(btrim(coalesce(p_filters ->> 'member_search', '')), '');
  v_role text := nullif(lower(btrim(coalesce(p_filters ->> 'role', ''))), '');
  v_book_search text := nullif(btrim(coalesce(p_filters ->> 'book_search', '')), '');
  v_words text[];
  v_from timestamptz := nullif(p_filters ->> 'from', '')::timestamptz;
  v_to timestamptz := nullif(p_filters ->> 'to', '')::timestamptz;
  v_total bigint;
  v_rows jsonb;
  v_count_borrowed bigint;
  v_count_overdue bigint;
  v_count_returned bigint;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  if v_scope not in ('borrowed', 'overdue', 'returned') then
    raise exception 'Unknown list. Use borrowed, overdue or returned.';
  end if;
  if v_member_search is not null then
    if char_length(v_member_search) > 120 then
      v_member_search := left(v_member_search, 120);
    end if;
    v_words := regexp_split_to_array(lower(v_member_search), '\s+');
  end if;

  -- Tab counts: the person/role/book filters across all three states.
  select count(*) filter (where l.returned_at is null),
         count(*) filter (where l.returned_at is null and l.due_at < now()),
         count(*) filter (where l.returned_at is not null)
    into v_count_borrowed, v_count_overdue, v_count_returned
  from public.book_loans l
  join public."usersData" u on u.id = l.user_profile_id
  join public.book_accession_numbers a on a.id = l.accession_id
  join public.books b on b.id = a.book_id
  where (v_member_search is null or (
          lower(u.library_id) like lower(v_member_search) || '%'
          or not exists (
            select 1 from unnest(v_words) as w
            where w <> ''
              and lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) not ilike '%' || w || '%')
          or extensions.word_similarity(
               lower(v_member_search),
               lower(concat_ws(' ', u.first_name, u.middle_initial,
                               u.surname, u.suffix))) > 0.6))
    and (v_role is null or lower(btrim(u.role::text)) = v_role)
    and (v_book_search is null
         or b.book_name ilike '%' || v_book_search || '%'
         or lower(a.accession_number) like lower(v_book_search) || '%');

  -- The list's matching total.
  select count(*) into v_total
  from public.book_loans l
  join public."usersData" u on u.id = l.user_profile_id
  join public.book_accession_numbers a on a.id = l.accession_id
  join public.books b on b.id = a.book_id
  where (v_scope <> 'borrowed' or l.returned_at is null)
    and (v_scope <> 'overdue'
         or (l.returned_at is null and l.due_at < now()))
    and (v_scope <> 'returned' or l.returned_at is not null)
    and (v_member_search is null or (
          lower(u.library_id) like lower(v_member_search) || '%'
          or not exists (
            select 1 from unnest(v_words) as w
            where w <> ''
              and lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) not ilike '%' || w || '%')
          or extensions.word_similarity(
               lower(v_member_search),
               lower(concat_ws(' ', u.first_name, u.middle_initial,
                               u.surname, u.suffix))) > 0.6))
    and (v_role is null or lower(btrim(u.role::text)) = v_role)
    and (v_book_search is null
         or b.book_name ilike '%' || v_book_search || '%'
         or lower(a.accession_number) like lower(v_book_search) || '%')
    and (v_from is null
         or (case when v_scope = 'returned'
                  then l.returned_at else l.borrowed_at end) >= v_from)
    and (v_to is null
         or (case when v_scope = 'returned'
                  then l.returned_at else l.borrowed_at end) < v_to);

  -- One page of rows.
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', y.id,
    'book_id', y.book_id,
    'book_name', y.book_name,
    'author', y.author,
    'call_number', y.call_number,
    'accession_number', y.accession_number,
    'member_id', y.member_id,
    'member_name', y.member_name,
    'library_id', y.library_id,
    'role', y.role,
    'avatar_url', y.avatar_url,
    'borrowed_at', y.borrowed_at,
    'due_at', y.due_at,
    'returned_at', y.returned_at,
    'recorded_by', y.recorded_by,
    'returned_by', y.returned_by,
    'is_overdue', y.is_overdue,
    'days_overdue', y.days_overdue,
    'days_late', y.days_late
  ) order by y.sort_due asc nulls last,
             case when v_scope = 'overdue' then y.sort_id end asc,
             y.sort_recent desc nulls last,
             case when v_scope <> 'overdue' then y.sort_id end desc), '[]'::jsonb)
  into v_rows
  from (
    select l.id, b.id as book_id, b.book_name, b.author, b.call_number,
      a.accession_number,
      u.id as member_id,
      lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix)
        as member_name,
      u.library_id, u.role, u.avatar_url,
      l.borrowed_at, l.due_at, l.returned_at,
      (select lirc_private.person_name(op.first_name, op.middle_initial, op.surname, op.suffix)
         from public."usersData" op where op.id = l.recorded_by) as recorded_by,
      (select lirc_private.person_name(op.first_name, op.middle_initial, op.surname, op.suffix)
         from public."usersData" op where op.id = l.returned_by) as returned_by,
      (l.returned_at is null and l.due_at < now()) as is_overdue,
      case when l.returned_at is null and l.due_at < now()
           then floor(extract(epoch from (now() - l.due_at)) / 86400)::int
           end as days_overdue,
      case when l.returned_at is not null and l.returned_at > l.due_at
           then floor(extract(epoch from (l.returned_at - l.due_at)) / 86400)::int
           end as days_late,
      case when v_scope = 'overdue' then l.due_at end as sort_due,
      l.id as sort_id,
      case when v_scope <> 'overdue'
           then coalesce(l.returned_at, l.borrowed_at) end as sort_recent
    from public.book_loans l
    join public."usersData" u on u.id = l.user_profile_id
    join public.book_accession_numbers a on a.id = l.accession_id
    join public.books b on b.id = a.book_id
    where (v_scope <> 'borrowed' or l.returned_at is null)
      and (v_scope <> 'overdue'
           or (l.returned_at is null and l.due_at < now()))
      and (v_scope <> 'returned' or l.returned_at is not null)
      and (v_member_search is null or (
            lower(u.library_id) like lower(v_member_search) || '%'
            or not exists (
              select 1 from unnest(v_words) as w
              where w <> ''
                and lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) not ilike '%' || w || '%')
            or extensions.word_similarity(
                 lower(v_member_search),
                 lower(concat_ws(' ', u.first_name, u.middle_initial,
                                 u.surname, u.suffix))) > 0.6))
      and (v_role is null or lower(btrim(u.role::text)) = v_role)
      and (v_book_search is null
           or b.book_name ilike '%' || v_book_search || '%'
           or lower(a.accession_number) like lower(v_book_search) || '%')
      and (v_from is null
           or (case when v_scope = 'returned'
                    then l.returned_at else l.borrowed_at end) >= v_from)
      and (v_to is null
           or (case when v_scope = 'returned'
                    then l.returned_at else l.borrowed_at end) < v_to)
    order by case when v_scope = 'overdue' then l.due_at end asc nulls last,
             case when v_scope = 'overdue' then l.id end asc,
             case when v_scope <> 'overdue'
                  then coalesce(l.returned_at, l.borrowed_at) end desc nulls last,
             case when v_scope <> 'overdue' then l.id end desc
    limit v_size offset (v_page - 1) * v_size
  ) y;

  return jsonb_build_object(
    'rows', v_rows,
    'total', v_total,
    'page', v_page,
    'page_size', v_size,
    'pages', greatest(ceil(v_total::numeric / v_size), 1),
    'has_prev', v_page > 1,
    'has_next', (v_page * v_size) < v_total,
    'counts', jsonb_build_object(
      'borrowed', v_count_borrowed,
      'overdue', v_count_overdue,
      'returned', v_count_returned));
end $$;

-- public.lirc_statistics_borrowing
create or replace function public.lirc_statistics_borrowing()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_year_id bigint;
  v_monthly jsonb;
  v_books_tree jsonb;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  select ay.id into v_year_id
  from public.semesters s
  join public.academic_years ay on ay.id = s.academic_year_id
  where s.is_active
  limit 1;

  with months as (
    select date_trunc('month', (now() at time zone 'Asia/Manila'))
             - (n || ' months')::interval as start_at
    from generate_series(11, 0, -1) as n
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'month', to_char(m.start_at, 'YYYY-MM'),
      'borrowed', (
        select count(*) from public.book_loans l
        where (l.borrowed_at at time zone 'Asia/Manila') >= m.start_at
          and (l.borrowed_at at time zone 'Asia/Manila') < m.start_at + interval '1 month'),
      'returned', (
        select count(*) from public.book_loans l
        where (l.returned_at at time zone 'Asia/Manila') >= m.start_at
          and (l.returned_at at time zone 'Asia/Manila') < m.start_at + interval '1 month'),
      'overdue', (
        select count(*) from public.book_loans l
        where (l.due_at at time zone 'Asia/Manila') >= m.start_at
          and (l.due_at at time zone 'Asia/Manila') < m.start_at + interval '1 month'
          and ((l.returned_at is null and l.due_at < now())
               or (l.returned_at is not null and l.returned_at > l.due_at)))
    ) order by m.start_at), '[]'::jsonb)
  into v_monthly
  from months m;

  with loan_rows as (
    select coalesce(d.name, '(No department)') as department,
           coalesce(prog.name, '(No program)') as program,
           case when lower(btrim(u.role::text)) = 'student'
                then en.year_level end as year_level,
           b.book_name
    from public.book_loans l
    join public."usersData" u on u.id = l.user_profile_id
    join public.book_accession_numbers a on a.id = l.accession_id
    join public.books b on b.id = a.book_id
    left join public.departments d on d.id = u.department_id
    left join public.programs prog on prog.id = u.program_id
    left join public.student_enrollments en
      on en.user_profile_id = u.id and en.academic_year_id = v_year_id
  ),
  dept_ranked as (
    select department, book_name, count(*) as n,
           sum(count(*)) over (partition by department) as total,
           row_number() over (partition by department
                              order by count(*) desc, book_name) as rn
    from loan_rows
    group by department, book_name
  ),
  dept_books as (
    select department, max(total) as total,
           jsonb_agg(jsonb_build_object('name', book_name, 'count', n)
                     order by n desc, book_name)
             filter (where rn <= 5) as books
    from dept_ranked
    group by department
  ),
  prog_ranked as (
    select department, program, book_name, count(*) as n,
           sum(count(*)) over (partition by department, program) as total,
           row_number() over (partition by department, program
                              order by count(*) desc, book_name) as rn
    from loan_rows
    group by department, program, book_name
  ),
  prog_books as (
    select department, program, max(total) as total,
           jsonb_agg(jsonb_build_object('name', book_name, 'count', n)
                     order by n desc, book_name)
             filter (where rn <= 5) as books
    from prog_ranked
    group by department, program
  ),
  year_ranked as (
    select department, program, year_level, book_name, count(*) as n,
           sum(count(*)) over (partition by department, program, year_level) as total,
           row_number() over (partition by department, program, year_level
                              order by count(*) desc, book_name) as rn
    from loan_rows
    where year_level is not null
    group by department, program, year_level, book_name
  ),
  year_books as (
    select department, program, year_level, max(total) as total,
           jsonb_agg(jsonb_build_object('name', book_name, 'count', n)
                     order by n desc, book_name)
             filter (where rn <= 5) as books
    from year_ranked
    group by department, program, year_level
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'label', d.department,
      'count', d.total,
      'books', d.books,
      'programs', coalesce((
        select jsonb_agg(jsonb_build_object(
            'label', p.program,
            'count', p.total,
            'books', p.books,
            'years', coalesce((
              select jsonb_agg(jsonb_build_object(
                  'label', y.year_level::text,
                  'count', y.total,
                  'books', y.books)
                  order by y.year_level)
              from year_books y
              where y.department = p.department and y.program = p.program),
              '[]'::jsonb))
          order by p.total desc, p.program)
        from prog_books p
        where p.department = d.department), '[]'::jsonb))
    order by d.total desc, d.department), '[]'::jsonb)
  into v_books_tree
  from dept_books d;

  return jsonb_build_object(
    'monthly', v_monthly,
    'totals', jsonb_build_object(
      'loans', (select count(*) from public.book_loans),
      'open', (select count(*) from public.book_loans where returned_at is null),
      'overdue', (
        select count(*) from public.book_loans
        where returned_at is null and due_at < now()),
      'returned', (
        select count(*) from public.book_loans where returned_at is not null),
      'avg_days', (
        select round(avg(extract(epoch from (returned_at - borrowed_at))
                         / 86400)::numeric, 1)
        from public.book_loans where returned_at is not null),
      'on_time', (
        select count(*) from public.book_loans
        where returned_at is not null and returned_at <= due_at),
      'late', (
        select count(*) from public.book_loans
        where returned_at is not null and returned_at > due_at)),
    'by_role', (
      select coalesce(jsonb_agg(jsonb_build_object('label', x.role, 'count', x.n)
                                order by x.n desc, x.role), '[]'::jsonb)
      from (
        select lower(btrim(u.role::text)) as role, count(*) as n
        from public.book_loans l
        join public."usersData" u on u.id = l.user_profile_id
        group by 1) x),
    'top_borrowers', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'name', lirc_private.person_name(x.first_name, x.middle_initial, x.surname, x.suffix),
          'library_id', x.library_id,
          'role', lower(btrim(x.role::text)),
          'count', x.n) order by x.n desc, x.surname, x.first_name), '[]'::jsonb)
      from (
        select u.id, u.first_name, u.middle_initial, u.surname, u.suffix,
               u.library_id, u.role, count(*) as n
        from public.book_loans l
        join public."usersData" u on u.id = l.user_profile_id
        group by u.id
        order by count(*) desc, u.surname, u.first_name
        limit 10) x),
    'top_books', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'name', x.book_name, 'author', x.author, 'count', x.n)
          order by x.n desc, x.book_name), '[]'::jsonb)
      from (
        select b.book_name, b.author, count(*) as n
        from public.book_loans l
        join public.book_accession_numbers a on a.id = l.accession_id
        join public.books b on b.id = a.book_id
        group by b.id, b.book_name, b.author
        order by count(*) desc, b.book_name
        limit 10) x),
    'books_tree', v_books_tree);
end $$;

-- public.lirc_statistics_attendance
create or replace function public.lirc_statistics_attendance()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_monthly jsonb;
  v_by_hour jsonb;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;

  with months as (
    select date_trunc('month', (now() at time zone 'Asia/Manila'))
             - (n || ' months')::interval as start_at
    from generate_series(11, 0, -1) as n
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'month', to_char(m.start_at, 'YYYY-MM'),
      'visits', (
        select count(*) from public.attendance a
        where (a.time_in at time zone 'Asia/Manila') >= m.start_at
          and (a.time_in at time zone 'Asia/Manila') < m.start_at + interval '1 month'),
      'unique_visitors', (
        select count(distinct a.user_profile_id) from public.attendance a
        where (a.time_in at time zone 'Asia/Manila') >= m.start_at
          and (a.time_in at time zone 'Asia/Manila') < m.start_at + interval '1 month')
    ) order by m.start_at), '[]'::jsonb)
  into v_monthly
  from months m;

  select coalesce(jsonb_agg(jsonb_build_object(
      'hour', h.hour, 'visits', coalesce(v.n, 0)) order by h.hour), '[]'::jsonb)
  into v_by_hour
  from generate_series(6, 21) as h(hour)
  left join (
    select extract(hour from (a.time_in at time zone 'Asia/Manila'))::int as hour,
           count(*) as n
    from public.attendance a
    where a.time_in >= now() - interval '12 months'
    group by 1) v on v.hour = h.hour;

  return jsonb_build_object(
    'monthly', v_monthly,
    'by_hour', v_by_hour,
    'totals', jsonb_build_object(
      'visits', (
        select count(*) from public.attendance
        where time_in >= now() - interval '12 months'),
      'unique_visitors', (
        select count(distinct user_profile_id) from public.attendance
        where time_in >= now() - interval '12 months'),
      'inside', (select count(*) from public.attendance where time_out is null),
      'avg_minutes', (
        select round(avg(extract(epoch from (time_out - time_in)) / 60)::numeric, 1)
        from public.attendance
        where time_in >= now() - interval '12 months' and time_out is not null),
      'busiest_day', (
        select jsonb_build_object('date', x.day, 'visits', x.n)
        from (
          select (a.time_in at time zone 'Asia/Manila')::date as day, count(*) as n
          from public.attendance a
          where a.time_in >= now() - interval '12 months'
          group by 1
          order by n desc, day
          limit 1) x)),
    'by_role', (
      select coalesce(jsonb_agg(jsonb_build_object('label', x.role, 'count', x.n)
                                order by x.n desc, x.role), '[]'::jsonb)
      from (
        select lower(btrim(a.role_at_visit)) as role, count(*) as n
        from public.attendance a
        where a.time_in >= now() - interval '12 months'
        group by 1) x),
    'by_purpose', (
      select coalesce(jsonb_agg(jsonb_build_object('label', x.purpose, 'count', x.n)
                                order by x.n desc, x.purpose), '[]'::jsonb)
      from (
        select a.purpose_of_visit as purpose, count(*) as n
        from public.attendance a
        where a.time_in >= now() - interval '12 months'
        group by 1) x),
    'by_department', (
      select coalesce(jsonb_agg(jsonb_build_object('label', x.label, 'count', x.n)
                                order by x.n desc, x.label), '[]'::jsonb)
      from (
        select coalesce(d.name, '(No department)') as label, count(*) as n
        from public.attendance a
        join public."usersData" u on u.id = a.user_profile_id
        left join public.departments d on d.id = u.department_id
        where a.time_in >= now() - interval '12 months'
        group by 1
        order by n desc, label
        limit 10) x),
    'top_visitors', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'name', lirc_private.person_name(x.first_name, x.middle_initial, x.surname, x.suffix),
          'library_id', x.library_id,
          'role', lower(btrim(x.role::text)),
          'count', x.n) order by x.n desc, x.surname, x.first_name), '[]'::jsonb)
      from (
        select u.id, u.first_name, u.middle_initial, u.surname, u.suffix,
               u.library_id, u.role, count(*) as n
        from public.attendance a
        join public."usersData" u on u.id = a.user_profile_id
        where a.time_in >= now() - interval '12 months'
        group by u.id
        order by count(*) desc, u.surname, u.first_name
        limit 10) x));
end $$;

-- public.lirc_statistics_borrowing
create or replace function public.lirc_statistics_borrowing(
  p_semester_id bigint default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_sem public.semesters%ROWTYPE;
  v_year_id bigint;
  v_start timestamptz;
  v_end timestamptz;
  v_monthly jsonb;
  v_books_tree jsonb;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  if p_semester_id is not null then
    select * into v_sem from public.semesters where id = p_semester_id;
  end if;
  if v_sem.id is null then
    select * into v_sem from public.semesters where is_active limit 1;
  end if;
  if v_sem.id is not null then
    v_start := v_sem.starts_on::timestamp at time zone 'Asia/Manila';
    v_end := (v_sem.ends_on + 1)::timestamp at time zone 'Asia/Manila';
    v_year_id := v_sem.academic_year_id;
  end if;

  -- Monthly lines across the semester's own months.
  with months as (
    select m.start_at
    from generate_series(
      date_trunc('month', v_sem.starts_on::timestamp),
      date_trunc('month', v_sem.ends_on::timestamp),
      interval '1 month') as m(start_at)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'month', to_char(m.start_at, 'YYYY-MM'),
      'borrowed', (
        select count(*) from public.book_loans l
        where v_start is not null
          and (l.borrowed_at at time zone 'Asia/Manila') >= m.start_at
          and (l.borrowed_at at time zone 'Asia/Manila') < m.start_at + interval '1 month'),
      'returned', (
        select count(*) from public.book_loans l
        where v_start is not null
          and (l.returned_at at time zone 'Asia/Manila') >= m.start_at
          and (l.returned_at at time zone 'Asia/Manila') < m.start_at + interval '1 month'),
      'overdue', (
        select count(*) from public.book_loans l
        where v_start is not null
          and (l.borrowed_at at time zone 'Asia/Manila') >= m.start_at
          and (l.borrowed_at at time zone 'Asia/Manila') < m.start_at + interval '1 month'
          and ((l.returned_at is null and l.due_at < now())
               or (l.returned_at is not null and l.returned_at > l.due_at)))
    ) order by m.start_at), '[]'::jsonb)
  into v_monthly
  from months m;

  -- The drill tree, scoped to the semester's loan cohort.
  with loan_rows as (
    select coalesce(d.name, '(No department)') as department,
           coalesce(prog.name, '(No program)') as program,
           case when lower(btrim(u.role::text)) = 'student'
                then en.year_level end as year_level,
           b.id as book_id, b.book_name
    from public.book_loans l
    join public."usersData" u on u.id = l.user_profile_id
    join public.book_accession_numbers a on a.id = l.accession_id
    join public.books b on b.id = a.book_id
    left join public.departments d on d.id = u.department_id
    left join public.programs prog on prog.id = u.program_id
    left join public.student_enrollments en
      on en.user_profile_id = u.id and en.academic_year_id = v_year_id
    where v_start is not null
      and l.borrowed_at >= v_start and l.borrowed_at < v_end
  ),
  dept_ranked as (
    select department, book_id, book_name, count(*) as n,
           sum(count(*)) over (partition by department) as total,
           row_number() over (partition by department
                              order by count(*) desc, book_name) as rn
    from loan_rows
    group by department, book_id, book_name
  ),
  dept_books as (
    select department, max(total) as total,
           jsonb_agg(jsonb_build_object('id', book_id, 'name', book_name, 'count', n)
                     order by n desc, book_name)
             filter (where rn <= 5) as books
    from dept_ranked
    group by department
  ),
  prog_ranked as (
    select department, program, book_id, book_name, count(*) as n,
           sum(count(*)) over (partition by department, program) as total,
           row_number() over (partition by department, program
                              order by count(*) desc, book_name) as rn
    from loan_rows
    group by department, program, book_id, book_name
  ),
  prog_books as (
    select department, program, max(total) as total,
           jsonb_agg(jsonb_build_object('id', book_id, 'name', book_name, 'count', n)
                     order by n desc, book_name)
             filter (where rn <= 5) as books
    from prog_ranked
    group by department, program
  ),
  year_ranked as (
    select department, program, year_level, book_id, book_name, count(*) as n,
           sum(count(*)) over (partition by department, program, year_level) as total,
           row_number() over (partition by department, program, year_level
                              order by count(*) desc, book_name) as rn
    from loan_rows
    where year_level is not null
    group by department, program, year_level, book_id, book_name
  ),
  year_books as (
    select department, program, year_level, max(total) as total,
           jsonb_agg(jsonb_build_object('id', book_id, 'name', book_name, 'count', n)
                     order by n desc, book_name)
             filter (where rn <= 5) as books
    from year_ranked
    group by department, program, year_level
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'label', d.department,
      'count', d.total,
      'books', d.books,
      'programs', coalesce((
        select jsonb_agg(jsonb_build_object(
            'label', p.program,
            'count', p.total,
            'books', p.books,
            'years', coalesce((
              select jsonb_agg(jsonb_build_object(
                  'label', y.year_level::text,
                  'count', y.total,
                  'books', y.books)
                  order by y.year_level)
              from year_books y
              where y.department = p.department and y.program = p.program),
              '[]'::jsonb))
          order by p.total desc, p.program)
        from prog_books p
        where p.department = d.department), '[]'::jsonb))
    order by d.total desc, d.department), '[]'::jsonb)
  into v_books_tree
  from dept_books d;

  return jsonb_build_object(
    'semester', jsonb_build_object(
      'id', v_sem.id,
      'name', v_sem.name,
      'year', (select ay.name from public.academic_years ay
               where ay.id = v_sem.academic_year_id)),
    'monthly', v_monthly,
    'totals', jsonb_build_object(
      'loans', (
        select count(*) from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end),
      'open', (
        select count(*) from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is null),
      'overdue', (
        select count(*) from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is null and l.due_at < now()),
      'returned', (
        select count(*) from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is not null),
      'avg_days', (
        select round(avg(extract(epoch from (l.returned_at - l.borrowed_at))
                         / 86400)::numeric, 1)
        from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is not null),
      'on_time', (
        select count(*) from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is not null and l.returned_at <= l.due_at),
      'late', (
        select count(*) from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is not null and l.returned_at > l.due_at)),
    'by_role', (
      select coalesce(jsonb_agg(jsonb_build_object('label', x.role, 'count', x.n)
                                order by x.n desc, x.role), '[]'::jsonb)
      from (
        select lower(btrim(u.role::text)) as role, count(*) as n
        from public.book_loans l
        join public."usersData" u on u.id = l.user_profile_id
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
        group by 1) x),
    'top_borrowers', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'name', lirc_private.person_name(x.first_name, x.middle_initial, x.surname, x.suffix),
          'id', x.id, 'library_id', x.library_id,
          'role', lower(btrim(x.role::text)),
          'count', x.n) order by x.n desc, x.surname, x.first_name), '[]'::jsonb)
      from (
        select u.id, u.first_name, u.middle_initial, u.surname, u.suffix,
               u.library_id, u.role, count(*) as n
        from public.book_loans l
        join public."usersData" u on u.id = l.user_profile_id
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
        group by u.id
        order by count(*) desc, u.surname, u.first_name
        limit 10) x),
    'top_books', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', x.book_id, 'name', x.book_name, 'author', x.author, 'count', x.n)
          order by x.n desc, x.book_name), '[]'::jsonb)
      from (
        select b.id as book_id, b.book_name, b.author, count(*) as n
        from public.book_loans l
        join public.book_accession_numbers a on a.id = l.accession_id
        join public.books b on b.id = a.book_id
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
        group by b.id, b.book_name, b.author
        order by count(*) desc, b.book_name
        limit 10) x),
    'books_tree', v_books_tree);
end $$;

-- public.lirc_statistics_attendance
create or replace function public.lirc_statistics_attendance(
  p_semester_id bigint default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_sem public.semesters%ROWTYPE;
  v_start timestamptz;
  v_end timestamptz;
  v_monthly jsonb;
  v_by_hour jsonb;
  v_visits_tree jsonb;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  if p_semester_id is not null then
    select * into v_sem from public.semesters where id = p_semester_id;
  end if;
  if v_sem.id is null then
    select * into v_sem from public.semesters where is_active limit 1;
  end if;
  if v_sem.id is not null then
    v_start := v_sem.starts_on::timestamp at time zone 'Asia/Manila';
    v_end := (v_sem.ends_on + 1)::timestamp at time zone 'Asia/Manila';
  end if;

  with months as (
    select m.start_at
    from generate_series(
      date_trunc('month', v_sem.starts_on::timestamp),
      date_trunc('month', v_sem.ends_on::timestamp),
      interval '1 month') as m(start_at)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'month', to_char(m.start_at, 'YYYY-MM'),
      'visits', (
        select count(*) from public.attendance a
        where v_start is not null
          and (a.time_in at time zone 'Asia/Manila') >= m.start_at
          and (a.time_in at time zone 'Asia/Manila') < m.start_at + interval '1 month'),
      'unique_visitors', (
        select count(distinct a.user_profile_id) from public.attendance a
        where v_start is not null
          and (a.time_in at time zone 'Asia/Manila') >= m.start_at
          and (a.time_in at time zone 'Asia/Manila') < m.start_at + interval '1 month')
    ) order by m.start_at), '[]'::jsonb)
  into v_monthly
  from months m;

  select coalesce(jsonb_agg(jsonb_build_object(
      'hour', h.hour, 'visits', coalesce(v.n, 0)) order by h.hour), '[]'::jsonb)
  into v_by_hour
  from generate_series(6, 21) as h(hour)
  left join (
    select extract(hour from (a.time_in at time zone 'Asia/Manila'))::int as hour,
           count(*) as n
    from public.attendance a
    where v_start is not null
      and a.time_in >= v_start and a.time_in < v_end
    group by 1) v on v.hour = h.hour;

  -- The visits tree: department → program → year level (at visit).
  with visit_rows as (
    select coalesce(d.name, '(No department)') as department,
           coalesce(prog.name, '(No program)') as program,
           case when lower(btrim(a.role_at_visit)) = 'student'
                then a.year_level end as year_level,
           a.user_profile_id,
           case when a.time_out is not null
                then extract(epoch from (a.time_out - a.time_in)) / 60
                end as minutes
    from public.attendance a
    join public."usersData" u on u.id = a.user_profile_id
    left join public.departments d on d.id = u.department_id
    left join public.programs prog on prog.id = u.program_id
    where v_start is not null
      and a.time_in >= v_start and a.time_in < v_end
  ),
  dept_stats as (
    select department as label, count(*) as visits,
           count(distinct user_profile_id) as unique_visitors,
           round(avg(minutes)::numeric, 1) as avg_minutes
    from visit_rows
    group by department
  ),
  prog_stats as (
    select department, program as label, count(*) as visits,
           count(distinct user_profile_id) as unique_visitors,
           round(avg(minutes)::numeric, 1) as avg_minutes
    from visit_rows
    group by department, program
  ),
  year_stats as (
    select department, program, year_level::text as label, count(*) as visits,
           count(distinct user_profile_id) as unique_visitors,
           round(avg(minutes)::numeric, 1) as avg_minutes
    from visit_rows
    where year_level is not null
    group by department, program, year_level
  ),
  dept_vis as (
    select department, jsonb_agg(jsonb_build_object(
        'id', x.id, 'name', x.name, 'library_id', x.library_id,
        'role', x.role, 'count', x.n) order by x.n desc, x.name) as visitors
    from (
      select vr.department, u.id,
             lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as name,
             u.library_id, lower(btrim(u.role::text)) as role,
             count(*) as n,
             row_number() over (partition by vr.department
                                order by count(*) desc,
                                         u.surname, u.first_name) as rn
      from visit_rows vr
      join public."usersData" u on u.id = vr.user_profile_id
      group by vr.department, u.id
    ) x
    where x.rn <= 5
    group by department
  ),
  prog_vis as (
    select department, program, jsonb_agg(jsonb_build_object(
        'id', x.id, 'name', x.name, 'library_id', x.library_id,
        'role', x.role, 'count', x.n) order by x.n desc, x.name) as visitors
    from (
      select vr.department, vr.program, u.id,
             lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as name,
             u.library_id, lower(btrim(u.role::text)) as role,
             count(*) as n,
             row_number() over (partition by vr.department, vr.program
                                order by count(*) desc,
                                         u.surname, u.first_name) as rn
      from visit_rows vr
      join public."usersData" u on u.id = vr.user_profile_id
      group by vr.department, vr.program, u.id
    ) x
    where x.rn <= 5
    group by department, program
  ),
  year_vis as (
    select department, program, year_level::text as label,
           jsonb_agg(jsonb_build_object(
        'id', x.id, 'name', x.name, 'library_id', x.library_id,
        'role', x.role, 'count', x.n) order by x.n desc, x.name) as visitors
    from (
      select vr.department, vr.program, vr.year_level, u.id,
             lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as name,
             u.library_id, lower(btrim(u.role::text)) as role,
             count(*) as n,
             row_number() over (partition by vr.department, vr.program, vr.year_level
                                order by count(*) desc,
                                         u.surname, u.first_name) as rn
      from visit_rows vr
      join public."usersData" u on u.id = vr.user_profile_id
      where vr.year_level is not null
      group by vr.department, vr.program, vr.year_level, u.id
    ) x
    where x.rn <= 5
    group by department, program, year_level
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'label', s.label,
      'visits', s.visits,
      'unique', s.unique_visitors,
      'avg_minutes', s.avg_minutes,
      'visitors', coalesce(dv.visitors, '[]'::jsonb),
      'programs', coalesce((
        select jsonb_agg(jsonb_build_object(
            'label', ps.label,
            'visits', ps.visits,
            'unique', ps.unique_visitors,
            'avg_minutes', ps.avg_minutes,
            'visitors', coalesce(pv.visitors, '[]'::jsonb),
            'years', coalesce((
              select jsonb_agg(jsonb_build_object(
                  'label', ys.label,
                  'visits', ys.visits,
                  'unique', ys.unique_visitors,
                  'avg_minutes', ys.avg_minutes,
                  'visitors', coalesce(yv.visitors, '[]'::jsonb))
                  order by ys.label)
              from year_stats ys
              left join year_vis yv
                on yv.department = ys.department
               and yv.program = ys.program
               and yv.label = ys.label
              where ys.department = ps.department
                and ys.program = ps.label), '[]'::jsonb))
          order by ps.visits desc, ps.label)
        from prog_stats ps
        left join prog_vis pv
          on pv.department = ps.department and pv.program = ps.label
        where ps.department = s.label), '[]'::jsonb))
    order by s.visits desc, s.label), '[]'::jsonb)
  into v_visits_tree
  from dept_stats s
  left join dept_vis dv on dv.department = s.label;

  return jsonb_build_object(
    'semester', jsonb_build_object(
      'id', v_sem.id,
      'name', v_sem.name,
      'year', (select ay.name from public.academic_years ay
               where ay.id = v_sem.academic_year_id)),
    'monthly', v_monthly,
    'by_hour', v_by_hour,
    'visits_tree', v_visits_tree,
    'totals', jsonb_build_object(
      'visits', (
        select count(*) from public.attendance a
        where v_start is not null
          and a.time_in >= v_start and a.time_in < v_end),
      'unique_visitors', (
        select count(distinct a.user_profile_id) from public.attendance a
        where v_start is not null
          and a.time_in >= v_start and a.time_in < v_end),
      'inside', (
        select count(*) from public.attendance a
        where v_start is not null
          and a.time_in >= v_start and a.time_in < v_end
          and a.time_out is null),
      'avg_minutes', (
        select round(avg(extract(epoch from (a.time_out - a.time_in)) / 60)::numeric, 1)
        from public.attendance a
        where v_start is not null
          and a.time_in >= v_start and a.time_in < v_end
          and a.time_out is not null),
      'busiest_day', (
        select jsonb_build_object('date', x.day, 'visits', x.n)
        from (
          select (a.time_in at time zone 'Asia/Manila')::date as day, count(*) as n
          from public.attendance a
          where v_start is not null
            and a.time_in >= v_start and a.time_in < v_end
          group by 1
          order by n desc, day
          limit 1) x)),
    'by_role', (
      select coalesce(jsonb_agg(jsonb_build_object('label', x.role, 'count', x.n)
                                order by x.n desc, x.role), '[]'::jsonb)
      from (
        select lower(btrim(a.role_at_visit)) as role, count(*) as n
        from public.attendance a
        where v_start is not null
          and a.time_in >= v_start and a.time_in < v_end
        group by 1) x),
    'by_purpose', (
      select coalesce(jsonb_agg(jsonb_build_object('label', x.purpose, 'count', x.n)
                                order by x.n desc, x.purpose), '[]'::jsonb)
      from (
        select a.purpose_of_visit as purpose, count(*) as n
        from public.attendance a
        where v_start is not null
          and a.time_in >= v_start and a.time_in < v_end
        group by 1) x),
    'by_department', (
      select coalesce(jsonb_agg(jsonb_build_object('label', x.label, 'count', x.n)
                                order by x.n desc, x.label), '[]'::jsonb)
      from (
        select coalesce(d.name, '(No department)') as label, count(*) as n
        from public.attendance a
        join public."usersData" u on u.id = a.user_profile_id
        left join public.departments d on d.id = u.department_id
        where v_start is not null
          and a.time_in >= v_start and a.time_in < v_end
        group by 1
        order by n desc, label
        limit 10) x),
    'top_visitors', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', x.id,
          'name', lirc_private.person_name(x.first_name, x.middle_initial, x.surname, x.suffix),
          'library_id', x.library_id,
          'role', lower(btrim(x.role::text)),
          'count', x.n) order by x.n desc, x.surname, x.first_name), '[]'::jsonb)
      from (
        select u.id, u.first_name, u.middle_initial, u.surname, u.suffix,
               u.library_id, u.role, count(*) as n
        from public.attendance a
        join public."usersData" u on u.id = a.user_profile_id
        where v_start is not null
          and a.time_in >= v_start and a.time_in < v_end
        group by u.id
        order by count(*) desc, u.surname, u.first_name
        limit 10) x));
end $$;

-- public.lirc_statistics_borrower
create or replace function public.lirc_statistics_borrower(
  p_profile_id bigint,
  p_semester_id bigint default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_sem public.semesters%ROWTYPE;
  v_start timestamptz;
  v_end timestamptz;
  u public."usersData"%ROWTYPE;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  if p_profile_id is null then
    raise exception 'A library member is required.';
  end if;
  select * into u from public."usersData" where id = p_profile_id;
  if not found then
    raise exception 'Library member not found.';
  end if;
  if p_semester_id is not null then
    select * into v_sem from public.semesters where id = p_semester_id;
  end if;
  if v_sem.id is null then
    select * into v_sem from public.semesters where is_active limit 1;
  end if;
  if v_sem.id is not null then
    v_start := v_sem.starts_on::timestamp at time zone 'Asia/Manila';
    v_end := (v_sem.ends_on + 1)::timestamp at time zone 'Asia/Manila';
  end if;

  return jsonb_build_object(
    'profile', jsonb_build_object(
      'id', u.id,
      'name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
      'library_id', u.library_id,
      'role', lower(btrim(u.role::text)),
      'avatar_url', u.avatar_url),
    'totals', jsonb_build_object(
      'loans', (
        select count(*) from public.book_loans l
        where l.user_profile_id = u.id
          and v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end),
      'open', (
        select count(*) from public.book_loans l
        where l.user_profile_id = u.id
          and v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is null),
      'overdue', (
        select count(*) from public.book_loans l
        where l.user_profile_id = u.id
          and v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is null and l.due_at < now()),
      'returned', (
        select count(*) from public.book_loans l
        where l.user_profile_id = u.id
          and v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is not null),
      'on_time', (
        select count(*) from public.book_loans l
        where l.user_profile_id = u.id
          and v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is not null and l.returned_at <= l.due_at),
      'late', (
        select count(*) from public.book_loans l
        where l.user_profile_id = u.id
          and v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is not null and l.returned_at > l.due_at),
      'avg_days', (
        select round(avg(extract(epoch from (l.returned_at - l.borrowed_at))
                         / 86400)::numeric, 1)
        from public.book_loans l
        where l.user_profile_id = u.id
          and v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is not null)),
    'books', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', x.book_id, 'name', x.book_name, 'count', x.n)
          order by x.n desc, x.book_name), '[]'::jsonb)
      from (
        select b.id as book_id, b.book_name, count(*) as n
        from public.book_loans l
        join public.book_accession_numbers a on a.id = l.accession_id
        join public.books b on b.id = a.book_id
        where l.user_profile_id = u.id
          and v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
        group by b.id, b.book_name
        order by count(*) desc, b.book_name
        limit 10) x),
    'loans', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', x.id,
          'book_id', x.book_id,
          'book_name', x.book_name,
          'accession_number', x.accession_number,
          'borrowed_at', x.borrowed_at,
          'due_at', x.due_at,
          'returned_at', x.returned_at,
          'is_overdue', x.is_overdue)
          order by x.borrowed_at desc, x.id desc), '[]'::jsonb)
      from (
        select l.id, b.id as book_id, b.book_name, a.accession_number,
               l.borrowed_at, l.due_at, l.returned_at,
               (l.returned_at is null and l.due_at < now()) as is_overdue
        from public.book_loans l
        join public.book_accession_numbers a on a.id = l.accession_id
        join public.books b on b.id = a.book_id
        where l.user_profile_id = u.id
          and v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
        order by l.borrowed_at desc, l.id desc
        limit 10) x));
end $$;

-- public.lirc_statistics_borrowers
create or replace function public.lirc_statistics_borrowers(
  p_semester_id bigint default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_sem public.semesters%ROWTYPE;
  v_start timestamptz;
  v_end timestamptz;
begin
  if lirc_private.library_operator_id() is null then
    raise exception 'Library operator access required.' using errcode = '42501';
  end if;
  if p_semester_id is not null then
    select * into v_sem from public.semesters where id = p_semester_id;
  end if;
  if v_sem.id is null then
    select * into v_sem from public.semesters where is_active limit 1;
  end if;
  if v_sem.id is not null then
    v_start := v_sem.starts_on::timestamp at time zone 'Asia/Manila';
    v_end := (v_sem.ends_on + 1)::timestamp at time zone 'Asia/Manila';
  end if;

  return jsonb_build_object(
    'semester', jsonb_build_object(
      'id', v_sem.id,
      'name', v_sem.name,
      'year', (select ay.name from public.academic_years ay
               where ay.id = v_sem.academic_year_id)),
    'totals', jsonb_build_object(
      'borrowers', (
        select count(distinct l.user_profile_id)
        from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end),
      'loans', (
        select count(*) from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end),
      'avg_loans', (
        select round(count(*)::numeric
                     / greatest(count(distinct l.user_profile_id), 1), 1)
        from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end),
      'repeat', (
        select count(*) from (
          select l.user_profile_id
          from public.book_loans l
          where v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
          group by l.user_profile_id
          having count(*) > 1) x),
      'first_time', (
        select count(*) from (
          select l.user_profile_id
          from public.book_loans l
          where v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
          group by l.user_profile_id) b
        where not exists (
          select 1 from public.book_loans before
          where before.user_profile_id = b.user_profile_id
            and before.borrowed_at < v_start)),
      'with_overdue', (
        select count(distinct l.user_profile_id)
        from public.book_loans l
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is null and l.due_at < now())),
    'top_borrowers', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', x.id,
          'name', lirc_private.person_name(x.first_name, x.middle_initial, x.surname, x.suffix),
          'library_id', x.library_id,
          'role', lower(btrim(x.role::text)),
          'count', x.n) order by x.n desc, x.surname, x.first_name), '[]'::jsonb)
      from (
        select u.id, u.first_name, u.middle_initial, u.surname, u.suffix,
               u.library_id, u.role, count(*) as n
        from public.book_loans l
        join public."usersData" u on u.id = l.user_profile_id
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
        group by u.id
        order by count(*) desc, u.surname, u.first_name
        limit 20) x),
    'overdue_now', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', x.id,
          'name', x.name,
          'library_id', x.library_id,
          'role', x.role,
          'count', x.n,
          'days', x.days) order by x.days desc, x.name), '[]'::jsonb)
      from (
        select u.id,
               lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as name,
               u.library_id, lower(btrim(u.role::text)) as role,
               count(*) as n,
               floor(extract(epoch from (now() - min(l.due_at))) / 86400)::int as days
        from public.book_loans l
        join public."usersData" u on u.id = l.user_profile_id
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
          and l.returned_at is null and l.due_at < now()
        group by u.id
        order by days desc, name
        limit 10) x),
    'by_role', (
      select coalesce(jsonb_agg(jsonb_build_object('label', x.role, 'count', x.n)
                                order by x.n desc, x.role), '[]'::jsonb)
      from (
        select lower(btrim(u.role::text)) as role,
               count(distinct l.user_profile_id) as n
        from public.book_loans l
        join public."usersData" u on u.id = l.user_profile_id
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
        group by 1) x),
    'by_department', (
      select coalesce(jsonb_agg(jsonb_build_object('label', x.label, 'count', x.n)
                                order by x.n desc, x.label), '[]'::jsonb)
      from (
        select coalesce(d.name, '(No department)') as label,
               count(distinct l.user_profile_id) as n
        from public.book_loans l
        join public."usersData" u on u.id = l.user_profile_id
        left join public.departments d on d.id = u.department_id
        where v_start is not null
          and l.borrowed_at >= v_start and l.borrowed_at < v_end
        group by 1
        order by n desc, label
        limit 10) x));
end $$;

-- lirc_private.borrow_report_rows
create or replace function lirc_private.borrow_report_rows(p_filters jsonb)
returns table (
  id bigint,
  user_profile_id bigint,
  member_name text,
  library_id text,
  role text,
  avatar_url text,
  department text,
  program text,
  book_name text,
  author text,
  call_number text,
  accession_number text,
  borrowed_at timestamptz,
  due_at timestamptz,
  returned_at timestamptz,
  is_overdue boolean,
  days_overdue integer,
  days_late integer,
  days_kept integer,
  recorded_by_name text,
  returned_by_name text)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_status text;
  v_role text;
  v_search_by text;
  v_search text;
  v_words text[];
  v_borrowed_from timestamptz;
  v_borrowed_to timestamptz;
  v_due_from timestamptz;
  v_due_to timestamptz;
  v_returned_from timestamptz;
  v_returned_to timestamptz;
begin
  if p_filters is null or jsonb_typeof(p_filters) <> 'object' then
    raise exception 'Invalid filters.';
  end if;

  v_status := lower(btrim(coalesce(p_filters ->> 'status', '')));
  if v_status not in ('', 'open', 'overdue', 'returned', 'late') then
    raise exception 'Invalid status filter.';
  end if;
  v_search_by := lower(btrim(coalesce(p_filters ->> 'search_by', 'member')));
  if v_search_by not in ('member', 'book') then
    raise exception 'Invalid search field.';
  end if;
  v_role := lower(btrim(coalesce(p_filters ->> 'role', '')));
  v_search := btrim(coalesce(p_filters ->> 'search', ''));
  if length(v_search) > 120 then
    raise exception 'Keep the search under 120 characters.';
  end if;
  v_words := array(
    select replace(replace(replace(lower(w), '\', '\\'), '%', '\%'), '_', '\_')
    from unnest(regexp_split_to_array(v_search, '\s+')) as w
    where w <> ''
  );

  v_borrowed_from := lirc_private.parse_ts(p_filters ->> 'borrowed_from');
  v_borrowed_to := lirc_private.parse_ts(p_filters ->> 'borrowed_to');
  v_due_from := lirc_private.parse_ts(p_filters ->> 'due_from');
  v_due_to := lirc_private.parse_ts(p_filters ->> 'due_to');
  v_returned_from := lirc_private.parse_ts(p_filters ->> 'returned_from');
  v_returned_to := lirc_private.parse_ts(p_filters ->> 'returned_to');

  return query
  select
    l.id,
    l.user_profile_id,
    lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as member_name,
    u.library_id,
    lower(btrim(u.role::text)) as role,
    u.avatar_url,
    d.name as department,
    p.name as program,
    b.book_name,
    b.author,
    b.call_number,
    a.accession_number,
    l.borrowed_at,
    l.due_at,
    l.returned_at,
    (l.returned_at is null and l.due_at < now()) as is_overdue,
    case when l.returned_at is null and l.due_at < now()
         then floor(extract(epoch from (now() - l.due_at)) / 86400)::int end as days_overdue,
    case when l.returned_at is not null and l.returned_at > l.due_at
         then floor(extract(epoch from (l.returned_at - l.due_at)) / 86400)::int end as days_late,
    case when l.returned_at is not null
         then floor(extract(epoch from (l.returned_at - l.borrowed_at)) / 86400)::int end as days_kept,
    (select lirc_private.person_name(op.first_name, op.middle_initial, op.surname, op.suffix)
       from public."usersData" op where op.id = l.recorded_by) as recorded_by_name,
    (select lirc_private.person_name(op.first_name, op.middle_initial, op.surname, op.suffix)
       from public."usersData" op where op.id = l.returned_by) as returned_by_name
  from public.book_loans l
  join public.book_accession_numbers a on a.id = l.accession_id
  join public.books b on b.id = a.book_id
  join public."usersData" u on u.id = l.user_profile_id
  left join public.departments d on d.id = u.department_id
  left join public.programs p on p.id = u.program_id
  where (v_borrowed_from is null or l.borrowed_at >= v_borrowed_from)
    and (v_borrowed_to is null or l.borrowed_at < v_borrowed_to)
    and (v_due_from is null or l.due_at >= v_due_from)
    and (v_due_to is null or l.due_at < v_due_to)
    and (v_returned_from is null
         or (l.returned_at is not null and l.returned_at >= v_returned_from))
    and (v_returned_to is null
         or (l.returned_at is not null and l.returned_at < v_returned_to))
    and (v_status = ''
         or (v_status = 'open' and l.returned_at is null)
         or (v_status = 'overdue' and l.returned_at is null and l.due_at < now())
         or (v_status = 'returned' and l.returned_at is not null)
         or (v_status = 'late' and l.returned_at is not null and l.returned_at > l.due_at))
    and (v_role = '' or lower(btrim(u.role::text)) = v_role)
    and (cardinality(v_words) = 0
         or (case v_search_by
               when 'book' then
                 not exists (select 1 from unnest(v_words) w
                             where b.book_name not ilike '%' || w || '%'
                               and a.accession_number not ilike '%' || w || '%')
               else
                 not exists (select 1 from unnest(v_words) w
                             where u.library_id not ilike '%' || w || '%'
                               and lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) not ilike '%' || w || '%')
             end));
end;
$$;

-- public.lirc_my_statistics
create or replace function public.lirc_my_statistics(
  p_semester_id bigint default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me public."usersData"%ROWTYPE;
  v_sem public.semesters%ROWTYPE;
  v_start timestamptz;
  v_end timestamptz;
  v_my_months jsonb;
begin
  select * into v_me from public."usersData"
  where id = lirc_private.my_profile_id();
  if not found then
    raise exception 'Sign in first.' using errcode = '42501';
  end if;
  if p_semester_id is not null then
    select * into v_sem from public.semesters where id = p_semester_id;
  end if;
  if v_sem.id is null then
    select * into v_sem from public.semesters where is_active limit 1;
  end if;
  if v_sem.id is not null then
    v_start := v_sem.starts_on::timestamp at time zone 'Asia/Manila';
    v_end := (v_sem.ends_on + 1)::timestamp at time zone 'Asia/Manila';
  end if;

  -- The caller's visits per month (the semester's months).
  with months as (
    select m.start_at
    from generate_series(
      date_trunc('month', v_sem.starts_on::timestamp),
      date_trunc('month', v_sem.ends_on::timestamp),
      interval '1 month') as m(start_at)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'month', to_char(m.start_at, 'YYYY-MM'),
      'visits', (
        select count(*) from public.attendance a
        where v_start is not null
          and a.user_profile_id = v_me.id
          and (a.time_in at time zone 'Asia/Manila') >= m.start_at
          and (a.time_in at time zone 'Asia/Manila') < m.start_at + interval '1 month'))
      order by m.start_at), '[]'::jsonb)
  into v_my_months
  from months m;

  return jsonb_build_object(
    'semester', jsonb_build_object(
      'id', v_sem.id,
      'name', v_sem.name,
      'year', (select ay.name from public.academic_years ay
               where ay.id = v_sem.academic_year_id)),
    'me', jsonb_build_object(
      'id', v_me.id,
      'library_id', v_me.library_id,
      'name', lirc_private.person_name(v_me.first_name, v_me.middle_initial, v_me.surname, v_me.suffix),
      'role', lower(btrim(v_me.role::text))),
    'borrowing', jsonb_build_object(
      'totals', jsonb_build_object(
        'loans', (
          select count(*) from public.book_loans l
          where l.user_profile_id = v_me.id
            and v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end),
        'open', (
          select count(*) from public.book_loans l
          where l.user_profile_id = v_me.id
            and v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
            and l.returned_at is null),
        'overdue', (
          select count(*) from public.book_loans l
          where l.user_profile_id = v_me.id
            and v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
            and l.returned_at is null and l.due_at < now()),
        'returned', (
          select count(*) from public.book_loans l
          where l.user_profile_id = v_me.id
            and v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
            and l.returned_at is not null),
        'on_time', (
          select count(*) from public.book_loans l
          where l.user_profile_id = v_me.id
            and v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
            and l.returned_at is not null and l.returned_at <= l.due_at),
        'late', (
          select count(*) from public.book_loans l
          where l.user_profile_id = v_me.id
            and v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
            and l.returned_at is not null and l.returned_at > l.due_at),
        'avg_days', (
          select round(avg(extract(epoch from (l.returned_at - l.borrowed_at))
                           / 86400)::numeric, 1)
          from public.book_loans l
          where l.user_profile_id = v_me.id
            and v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
            and l.returned_at is not null)),
      'books', (
        select coalesce(jsonb_agg(jsonb_build_object(
            'id', x.book_id, 'name', x.book_name, 'count', x.n)
            order by x.n desc, x.book_name), '[]'::jsonb)
        from (
          select b.id as book_id, b.book_name, count(*) as n
          from public.book_loans l
          join public.book_accession_numbers a on a.id = l.accession_id
          join public.books b on b.id = a.book_id
          where l.user_profile_id = v_me.id
            and v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
          group by b.id, b.book_name
          order by count(*) desc, b.book_name
          limit 10) x),
      'loans', (
        select coalesce(jsonb_agg(jsonb_build_object(
            'id', x.id,
            'book_id', x.book_id,
            'book_name', x.book_name,
            'accession_number', x.accession_number,
            'borrowed_at', x.borrowed_at,
            'due_at', x.due_at,
            'returned_at', x.returned_at,
            'is_overdue', x.is_overdue)
            order by x.borrowed_at desc, x.id desc), '[]'::jsonb)
        from (
          select l.id, b.id as book_id, b.book_name, a.accession_number,
                 l.borrowed_at, l.due_at, l.returned_at,
                 (l.returned_at is null and l.due_at < now()) as is_overdue
          from public.book_loans l
          join public.book_accession_numbers a on a.id = l.accession_id
          join public.books b on b.id = a.book_id
          where l.user_profile_id = v_me.id
            and v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
          order by l.borrowed_at desc, l.id desc
          limit 10) x)),
    'attendance', jsonb_build_object(
      'totals', jsonb_build_object(
        'visits', (
          select count(*) from public.attendance a
          where a.user_profile_id = v_me.id
            and v_start is not null
            and a.time_in >= v_start and a.time_in < v_end),
        'days', (
          select count(distinct (a.time_in at time zone 'Asia/Manila')::date)
          from public.attendance a
          where a.user_profile_id = v_me.id
            and v_start is not null
            and a.time_in >= v_start and a.time_in < v_end),
        'avg_minutes', (
          select round(avg(extract(epoch from (a.time_out - a.time_in))
                           / 60)::numeric, 1)
          from public.attendance a
          where a.user_profile_id = v_me.id
            and v_start is not null
            and a.time_in >= v_start and a.time_in < v_end
            and a.time_out is not null),
        'last_visit_day', (
          select to_char(max(a.time_in) at time zone 'Asia/Manila',
                         'YYYY-MM-DD')
          from public.attendance a
          where a.user_profile_id = v_me.id)),
      'months', v_my_months,
      'recent', (
        select coalesce(jsonb_agg(jsonb_build_object(
            'id', x.id,
            'time_in', x.time_in,
            'time_out', x.time_out,
            'minutes', x.minutes,
            'purpose', x.purpose,
            'is_open', x.is_open)
            order by x.time_in desc, x.id desc), '[]'::jsonb)
        from (
          select a.id, a.time_in, a.time_out,
                 case when a.time_out is null then null
                      else round(extract(epoch from a.time_out - a.time_in) / 60)
                      end as minutes,
                 a.purpose_of_visit as purpose,
                 a.time_out is null as is_open
          from public.attendance a
          where a.user_profile_id = v_me.id
            and v_start is not null
            and a.time_in >= v_start and a.time_in < v_end
          order by a.time_in desc, a.id desc
          limit 10) x)),
    'department', jsonb_build_object(
      'id', v_me.department_id,
      'name', (select d.name from public.departments d
               where d.id = v_me.department_id),
      -- The caller's own department only; members without a department
      -- fall back to the whole library (there is nothing to scope to).
      'popular', (
        select coalesce(jsonb_agg(jsonb_build_object(
            'id', x.book_id, 'name', x.book_name, 'author', x.author,
            'count', x.n)
            order by x.n desc, x.book_name), '[]'::jsonb)
        from (
          select b.id as book_id, b.book_name, b.author, count(*) as n
          from public.book_loans l
          join public.book_accession_numbers a on a.id = l.accession_id
          join public.books b on b.id = a.book_id
          join public."usersData" u on u.id = l.user_profile_id
          where v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
            and (v_me.department_id is null
                 or u.department_id = v_me.department_id)
          group by b.id, b.book_name, b.author
          order by count(*) desc, b.book_name
          limit 10) x),
      -- The department's real programs, by borrowing activity: each
      -- program's loan count and its most borrowed titles (top 5), like the
      -- borrowing statistics' program level. Borrowers without a program on
      -- record are not listed as a group.
      'programs', (
        select coalesce(jsonb_agg(jsonb_build_object(
            'id', x.program_id,
            'name', x.program_name,
            'count', x.n,
            'books', x.books)
            order by x.n desc, x.program_name), '[]'::jsonb)
        from (
          select p.id as program_id,
                 p.name as program_name,
                 count(*) as n,
                 (
                   select coalesce(jsonb_agg(jsonb_build_object(
                       'id', y.book_id, 'name', y.book_name, 'count', y.n)
                       order by y.n desc, y.book_name), '[]'::jsonb)
                   from (
                     select b.id as book_id, b.book_name, count(*) as n
                     from public.book_loans l2
                     join public.book_accession_numbers a2
                       on a2.id = l2.accession_id
                     join public.books b on b.id = a2.book_id
                     join public."usersData" u2 on u2.id = l2.user_profile_id
                     where v_start is not null
                       and l2.borrowed_at >= v_start
                       and l2.borrowed_at < v_end
                       and u2.program_id = p.id
                       and (v_me.department_id is null
                            or u2.department_id = v_me.department_id)
                     group by b.id, b.book_name
                     order by count(*) desc, b.book_name
                     limit 5) y) as books
          from public.book_loans l
          join public."usersData" u on u.id = l.user_profile_id
          join public.programs p on p.id = u.program_id
          where v_start is not null
            and l.borrowed_at >= v_start and l.borrowed_at < v_end
            and (v_me.department_id is null
                 or u.department_id = v_me.department_id)
          group by p.id, p.name
          order by count(*) desc, p.name
          limit 12) x)));
end $$;

-- public.lirc_system_borrow
create or replace function public.lirc_system_borrow(
  p_accession text,
  p_library_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me bigint;
  v_accession text;
  v_card text;
  v_accession_id bigint;
  v_status text;
  u public."usersData"%ROWTYPE;
  v_role text;
  v_active_year_id bigint;
  v_in_active_year boolean;
  e public.student_enrollments%ROWTYPE;
  v_loan_id bigint;
  v_due timestamptz;
  b public.books%ROWTYPE;
begin
  v_me := lirc_private.system_borrow_id();
  if v_me is null then
    raise exception 'Borrowing station access required.' using errcode = '42501';
  end if;

  v_accession := btrim(coalesce(p_accession, ''));
  if v_accession ~ '^\*.*\*$' and length(v_accession) > 2 then
    v_accession := substr(v_accession, 2, length(v_accession) - 2);
  end if;
  if v_accession = '' or length(v_accession) > 120 then
    raise exception 'Enter a valid accession number.';
  end if;

  v_card := btrim(coalesce(p_library_id, ''));
  if v_card = '' or length(v_card) > 120 then
    raise exception 'Enter a valid library card.';
  end if;

  select a.id, a.status into v_accession_id, v_status
  from public.book_accession_numbers a
  where a.accession_number = v_accession;
  if v_accession_id is null then
    raise exception 'Accession number % was not found.', v_accession;
  end if;
  if v_status is not null and lower(btrim(v_status)) not in ('available', '') then
    raise exception 'This copy is marked "%". Ask the librarian for help.', v_status;
  end if;
  if exists (
    select 1 from public.book_loans l
    where l.accession_id = v_accession_id and l.returned_at is null
  ) then
    raise exception 'This copy is already on loan.';
  end if;

  select * into u from public."usersData"
  where lower(library_id) = lower(v_card)
  for update;
  if not found then
    raise exception 'Library card % was not found.', v_card;
  end if;
  v_role := lower(btrim(u.role::text));

  -- Students need a validated enrollment for the school year the loan
  -- starts in (the same rule as the desk).
  if v_role = 'student' then
    select ay.id into v_active_year_id
    from public.semesters s
    join public.academic_years ay on ay.id = s.academic_year_id
    where s.is_active
    limit 1;
    if v_active_year_id is not null then
      select exists (
        select 1 from public.academic_years ay
        where ay.id = v_active_year_id
          and (now() at time zone 'Asia/Manila')::date
              between ay.starts_on and ay.ends_on
      ) into v_in_active_year;
      if v_in_active_year then
        select * into e from public.student_enrollments
        where user_profile_id = u.id and academic_year_id = v_active_year_id;
        if not found then
          raise exception 'Student has no annual validation for this school year. See the library staff.';
        end if;
        if e.status <> 'enrolled' or e.validated_at is null
           or e.year_level is null or e.year_level not between 1 and 4 then
          raise exception 'Student is not validated as enrolled (status: %). See the library staff.',
            e.status;
        end if;
      end if;
    end if;
  end if;

  -- The standard loan period (same default as the desk).
  v_due := now() + interval '7 days';

  begin
    insert into public.book_loans
      (accession_id, user_profile_id, borrowed_at, due_at, recorded_by)
    values
      (v_accession_id, u.id, now(), v_due, v_me)
    returning id into v_loan_id;
  exception when unique_violation then
    raise exception 'This copy was just borrowed. Choose another copy.';
  end;

  select b2.* into b
  from public.books b2
  join public.book_accession_numbers a2 on a2.book_id = b2.id
  where a2.id = v_accession_id;

  return jsonb_build_object(
    'id', v_loan_id,
    'book_name', b.book_name,
    'author', b.author,
    'accession_number', v_accession,
    'member_name', lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix),
    'library_id', u.library_id,
    'due_at', v_due);
end;
$$;

-- public.lirc_system_borrow_recent
create or replace function public.lirc_system_borrow_recent()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me bigint;
begin
  v_me := lirc_private.system_borrow_id();
  if v_me is null then
    raise exception 'Borrowing station access required.' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
        'id', x.id,
        'book_name', x.book_name,
        'accession_number', x.accession_number,
        'member_name', x.member_name,
        'library_id', x.library_id,
        'borrowed_at', x.borrowed_at,
        'due_at', x.due_at)
        order by x.borrowed_at desc, x.id desc)
    from (
      select l.id, b.book_name, a.accession_number,
             lirc_private.person_name(u.first_name, u.middle_initial, u.surname, u.suffix) as member_name,
             u.library_id, l.borrowed_at, l.due_at
      from public.book_loans l
      join public.book_accession_numbers a on a.id = l.accession_id
      join public.books b on b.id = a.book_id
      join public."usersData" u on u.id = l.user_profile_id
      where l.recorded_by = v_me
      order by l.borrowed_at desc, l.id desc
      limit 10
    ) x), '[]'::jsonb);
end;
$$;

notify pgrst, 'reload schema';
commit;
